":\"La Sorcière Progestative\",\"emo\":\"💉\",\"chs\":[\"C13\",\"C14\"],\"lvl\":\"Le Laboratoire des Hormones\"},{\"name\":\"Le Gardien du Post-partum\",\"emo\":\"🤱\",\"chs\":[\"C15\",\"C16\"],\"lvl\":\"La Maternité Enchantée\"},{\"name\":\"Le Grand Logisticien\",\"emo\":\"📦\",\"chs\":[\"C17\",\"C18\",\"C19\"],\"lvl\":\"La Citadelle du Centre PF\"}]}<%/script>\n<script type=\"application/json\" id=\"app-img\">{}<%/script>\n<script type=\"application/json\" id=\"app-edits\">{}<%/script>\n<script id=\"app-js\">\"use strict\";\n/* ============================================================\n   PORTAIL DE RÉVISION INFAS — MOTEUR (présent dans toutes les versions)\n   Données : #app-data · Images : #app-img · Modifications : #app-edits\n   L'éditeur (#ed-js) est un fichier séparé, absent de la version lecture seule.\n   Règle : aucun texte affiché en dur — tout passe par T()/Tx() avec une clé\n   littérale entre apostrophes simples, pour que l'éditeur puisse tout lister.\n   ============================================================ */\nconst $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];\nconst esc=s=>String(s==null?'':s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst jsq=s=>esc(String(s).replace(/\\\\/g,'\\\\\\\\').replace(/'/g,\"\\\\'\"));\nconst clone=o=>JSON.parse(JSON.stringify(o));\nconst DATA0=JSON.parse($('#app-data').textContent);\nconst IMG=JSON.parse(($('#app-img')||{}).textContent||'{}');\nconst EMB=JSON.parse(($('#app-edits')||{}).textContent||'{}');\nconst META=Object.assign({appId:'portail',brand:['RÉVISION','INFAS'],subtitle:'',signature:'Créé par <b>Daniel Noufe</b> · INFAS',title:'Révision — INFAS',defaultPalette:0,exam:{n:40,min:40}},DATA0.meta||{});\nconst APPID=META.appId, SKEY=APPID+'_progress_v1', EKEY=APPID+'_edits_v1', HKEY=APPID+'_edits_hist_v1';\nlet RO=true, EDITMODE=false;\nfunction blankE(){return{rev:0,texts:{},layout:{},tiles:{},menu:null,palette:null,font:null,gts:1,content:{}}}\nfunction normE(e){const b=blankE();e=e&&typeof e==='object'?clone(e):{};Object.keys(b).forEach(k=>{if(e[k]!==undefined)b[k]=e[k]});b.base=e.base;b.rev=e.rev||0;return b}\nlet E=normE(EMB);\n\n/* ---------- textes modifiables ---------- */\nconst TREG={};\nfunction tget(k,d){const t=E.texts;return t&&Object.prototype.hasOwnProperty.call(t,k)?t[k]:d}\nfunction tfill(s,v){return v?String(s).replace(/\\{(\\w+)\\}/g,(m,k)=>v[k]!=null?v[k]:m):String(s)}\nfunction T(k,d,v){if(!TREG[k])TREG[k]={d,v:v?Object.keys(v):[]};return '<span data-t=\"'+k+'\">'+tfill(tget(k,d),v)+'</span>'}\nfunction Tx(k,d,v){if(!TREG[k])TREG[k]={d,v:v?Object.keys(v):[],plain:1};return tfill(tget(k,d),v).replace(/<[^>]+>/g,'')}\n\n/* ---------- contenu (données + corrections de l'éditeur) ---------- */\nlet DATA,CH,QBY,QI,IMGI,COURSE_BY,PARTS,PARTM,SRCN,CARDS;\nfunction applyContent(){const d=clone(DATA0),c=E.content||{};\n ['chapters','questions','course','images','glossary','numbers','resPhysio','tabRes','tabComp','bosses','parts','sources'].forEach(k=>{if(!Array.isArray(d[k]))d[k]=[]});\n if(!d.resAnat||typeof d.resAnat!=='object')d.resAnat={};\n if(!d.parts.length){const ids=[...new Set(d.chapters.map(x=>x.part||'P'))];d.parts=ids.map(id=>({id,name:id,tag:id,emo:'📘'}))}\n d.chapters.forEach(x=>{if(!x.part)x.part=d.parts[0].id;if(!x.pages)x.pages=[0,0];if(!x.emo)x.emo='📘';if(!x.short)x.short=x.title});\n if(c.parts)d.parts.forEach(p=>Object.assign(p,c.parts[p.id]||{}));\n if(c.chapters)d.chapters.forEach(x=>Object.assign(x,c.chapters[x.id]||{}));\n d.questions.forEach((q,i)=>{if(q.id==null)q.id=i});\n if(c.q)d.questions=d.questions.map(q=>c.q[q.id]?Object.assign({},q,c.q[q.id],{id:q.id}):q);\n if(Array.isArray(c.qAdd))d.questions=d.questions.concat(c.qAdd);\n if(Array.isArray(c.qDel)){const s=new Set(c.qDel);d.questions=d.questions.filter(q=>!s.has(q.id))}\n if(Array.isArray(c.glossary))d.glossary=c.glossary;\n if(Array.isArray(c.numbers))d.numbers=c.numbers;\n if(c.course)d.course.forEach(p=>{const k=p.src+'-'+p.page;if(c.course[k]!=null)p.html=c.course[k]});\n if(!d.sources.length)d.sources=d.parts.map(p=>({id:p.id,name:p.name}));\n if(d.prepa){const P=d.prepa;let all=(P.q||[]).map(q=>Object.assign({},q,{hors:0})).concat((P.hors||[]).map(h=>{const o=(h.options||[]).filter(Boolean);return Object.assign({type:o.length?'qcm':'vf',options:o.length?o:['Vrai','Faux'],answer:null,exp:'',ch:'PX'},h,{hors:1})}));\n  if(c.pq)all=all.map(q=>c.pq[q.id]?Object.assign({},q,c.pq[q.id],{id:q.id}):q);\n  all.sort((a,b)=>(a.num||0)-(b.num||0));P.q=all.filter(q=>!q.hors);P.hors=all.filter(q=>q.hors)}\n DATA=d;index()}\nfunction index(){CH={};DATA.chapters.forEach(c=>CH[c.id]=c);QBY={};QI={};DATA.questions.forEach(q=>{QI[q.id]=q;(QBY[q.ch]=QBY[q.ch]||[]).push(q)});PREPA().q.forEach(q=>{QI[q.id]=q});((DATA.prepa||{}).chs||[]).forEach(c=>{if(!CH[c.id])CH[c.id]=Object.assign({emo:'📕',short:c.title,part:'',pages:[0,0]},c)});\n IMGI={};DATA.images.forEach(i=>IMGI[i.id]=i);COURSE_BY={};DATA.course.forEach(p=>{if(!p.imgs)p.imgs=[];(COURSE_BY[p.ch]=COURSE_BY[p.ch]||[]).push(p)});\n PARTS=DATA.parts;PARTM={};PARTS.forEach(p=>PARTM[p.id]=p);SRCN={};DATA.sources.forEach(s=>SRCN[s.id]=s.name);buildCards()}\nconst chOf=id=>CH[id]||{id,title:id,short:id,emo:'📘',part:(PARTS[0]||{}).id,pages:[0,0]};\nconst srcName=s=>SRCN[s]||(PARTM[s]&&PARTM[s].name)||s||'';\nconst partIdx=p=>Math.max(0,PARTS.findIndex(x=>x.id===p));\nconst PAGEKEY=p=>p.src+'-'+p.page;\nconst TYPES=['qcm','qcd','vf','saisie','cas','img'];\nfunction typeLabel(t){switch(t){case'qcm':return Tx('type.qcm','QCM · réponse unique');case'qcd':return Tx('type.qcd','QCM · plusieurs réponses');case'vf':return Tx('type.vf','Vrai / Faux');case'saisie':return Tx('type.saisie','QROC · réponse courte');case'cas':return Tx('type.cas','Cas clinique');case'img':return Tx('type.img','Lecture de schéma');default:return t}}\nfunction levels(){return[[0,Tx('level.1','Recrue')],[600,Tx('level.2','Externe')],[1500,Tx('level.3','Interne')],[3000,Tx('level.4','Major de promo')],[5000,Tx('level.5','Chef de clinique')],[8000,Tx('level.6','Professeur')],[12000,Tx('level.7','Légende de l’INFAS')]]}\nconst AVATARS={\n 'Soignantes et soignants':['👩🏾‍⚕️','👨🏾‍⚕️','🧑🏾‍⚕️','👩🏿‍⚕️','👨🏿‍⚕️','🧑🏿‍⚕️','👩🏽‍⚕️','👨🏽‍⚕️','👩🏾‍🔬','👨🏾‍🔬','👩🏾‍🏫','👨🏾‍🏫'],\n 'Étudiants et personnages':['👩🏾‍🎓','👨🏾‍🎓','🧑🏾‍🎓','👩🏿‍🎓','👨🏿‍🎓','🧕🏾','👳🏾‍♂️','👸🏾','🤴🏾','🦸🏾‍♀️','🦸🏾‍♂️','🧙🏾‍♂️','🧝🏾‍♀️','🥷🏾','🧑🏾‍🚀','👩🏾‍💻','👨🏾‍💻','🕵🏾‍♀️','💃🏾','🕺🏾'],\n 'Santé et science':['🦴','🦷','🧠','🫀','🫁','💉','🩺','💊','🧬','🔬','🩻','🩹','🧪','🏥','🚑','🦿'],\n 'Animaux':['🦁','🐘','🦒','🦓','🐆','🦏','🐊','🦜','🦉','🐢','🐬','🦋','🐝','🦅','🐺','🐼'],\n 'Symboles':['⭐','🌟','💎','🔥','⚡','🌈','🍀','🎯','🏆','🎓','📚','💡','🛡️','⚔️','🌍','❤️']};\n\n/* ---------- progression de l'étudiant ---------- */\nlet S;\nfunction load(){let d={};try{d=JSON.parse(localStorage.getItem(SKEY)||'{}')}catch(e){}\n return Object.assign({name:'',avatar:'🎓',xp:0,streak:{last:'',count:0},qs:{},save:null,bosses:{},lt:{},ann:{},hl:['#FFE08A','#A8E6CF','#FFB3BA'],read:{},hist:[],exams:[],flashKnown:0,theme:null},d)}\nfunction save(){try{localStorage.setItem(SKEY,JSON.stringify(S))}catch(e){}}\nfunction today(){const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}\nfunction touchStreak(){const t=today();if(S.streak.last===t)return;const y=new Date(Date.now()-864e5);const ys=y.getFullYear()+'-'+String(y.getMonth()+1).padStart(2,'0')+'-'+String(y.getDate()).padStart(2,'0');S.streak.count=(S.streak.last===ys)?S.streak.count+1:1;S.streak.last=t;save()}\nfunction addXP(n){S.xp+=n;save()}\nfunction level(){const LV=levels();let i=0;LV.forEach((l,k)=>{if(S.xp>=l[0])i=k});const cur=LV[i][0],nxt=LV[i+1]?LV[i+1][0]:cur+5000;return{n:i+1,name:LV[i][1],pct:Math.min(100,(S.xp-cur)/(nxt-cur)*100)}}\n\n/* ---------- palettes (7, dont 3 blanches) & police ---------- */\nconst PALETTES_DEF=[\n {n:'Vert forêt',h1:'#0B3B26',h2:'#13693F',acc:'#22A95B',acc2:'#8BCF3F',bg:'#EEF6F0'},\n {n:'Bleu nuit & or',h1:'#0E1F45',h2:'#23407E',acc:'#E89B00',acc2:'#4C8DFF',bg:'#EEF2FA'},\n {n:'Violet & rose',h1:'#2A1446',h2:'#5B2A86',acc:'#E2468C',acc2:'#A77BFF',bg:'#F4F0FA'},\n {n:'Rouge & noir',h1:'#141414',h2:'#4A1015',acc:'#D7263D',acc2:'#FF7A7A',bg:'#F6F1F1'},\n {n:'Blanc & émeraude',h1:'#0F5132',h2:'#1E7A4C',acc:'#16A34A',acc2:'#34D399',bg:'#FFFFFF',w:1},\n {n:'Blanc & azur',h1:'#0B3A6E',h2:'#1D5FA8',acc:'#2563EB',acc2:'#38BDF8',bg:'#FFFFFF',w:1},\n {n:'Blanc & corail',h1:'#5A1E12',h2:'#A3402B',acc:'#F0614A',acc2:'#FFB199',bg:'#FFFFFF',w:1}];\nconst PALETTES=()=>(Array.isArray(META.palettes)&&META.palettes.length?META.palettes:PALETTES_DEF);\nfunction hx(h){h=String(h).replace('#','');if(h.length===3)h=h.split('').map(c=>c+c).join('');return[0,2,4].map(i=>parseInt(h.substr(i,2),16)||0)}\nfunction mixc(a,b,t){const A=hx(a),B=hx(b);return'#'+A.map((v,i)=>Math.round(v+(B[i]-v)*t).toString(16).padStart(2,'0')).join('')}\nfunction lum(h){const[r,g,b]=hx(h);return(0.299*r+0.587*g+0.114*b)/255}\nfunction authorPalette(){const P=PALETTES(),p=E.palette;if(p&&p.custom)return p.custom;const i=p&&p.pal!=null?p.pal:(META.defaultPalette||0);return P[i]||P[0]}\nfunction palette(){const P=PALETTES(),t=S&&S.theme;if(t&&t.custom)return t.custom;if(t&&t.pal!=null&&P[t.pal])return P[t.pal];return authorPalette()}\nfunction applyLook(){const t=palette(),r=document.documentElement.style,set=(k,v)=>r.setProperty(k,v);\n set('--h1',t.h1);set('--h2',t.h2);set('--h3',mixc(t.h2,'#ffffff',.15));set('--coral',t.acc);set('--coral-d',mixc(t.acc,'#000000',.18));set('--turq',t.acc2);set('--bg',t.bg);\n set('--mint',mixc(t.acc,'#ffffff',.82));set('--line',mixc(t.h2,'#ffffff',.86));set('--plum1',mixc(t.h1,'#000000',.1));set('--plum2',mixc(t.h2,t.acc,.3));\n set('--tint',mixc(t.h2,'#ffffff',.86));set('--tint2',mixc(t.h2,'#ffffff',.93));set('--tint3',mixc(t.acc,'#ffffff',.88));\n set('--blob',t.acc2+'59');set('--launchInk',lum(mixc(t.acc,t.acc2,.5))>0.55?'#1a1a1a':'#ffffff');\n if(t.w){set('--hdrA','#ffffff');set('--hdrB',mixc(t.acc,'#ffffff',.9));set('--hdrInk',t.h1);set('--hdrSh','0 4px 18px rgba(0,0,0,.07)');set('--brand1a',t.acc);set('--brand1b',t.h2);set('--b2a',t.h1);set('--b2b',t.acc);set('--sigB',t.acc);\n  set('--navBg','#ffffff');set('--navInk',mixc(t.h1,'#ffffff',.4));set('--navOn',t.h1);set('--cardBd','1px solid '+mixc(t.h2,'#ffffff',.85))}\n else{set('--hdrA',t.h1);set('--hdrB',t.h2);set('--hdrInk','#ffffff');set('--hdrSh','none');set('--brand1a',mixc(t.acc2,'#ffffff',.55));set('--brand1b',mixc(t.acc2,'#ffffff',.15));set('--b2a','#FFE08A');set('--b2b','#FFC24B');set('--sigB','var(--gold)');\n  set('--navBg',t.h1);set('--navInk',mixc(t.h1,'#ffffff',.75));set('--navOn','#ffffff');set('--cardBd','none')}\n S.hl.forEach((c,i)=>set('--hl'+i,c));\n const f=E.font&&E.font.family;if(f)set('--font','\"'+String(f).replace(/[\"\\\\]/g,'')+'\"');else r.removeProperty('--font');\n set('--gts',String(E.gts||1));\n const m=$('meta[name=theme-color]');if(m)m.content=t.w?'#ffffff':t.h1;document.title=Tx('meta.title',META.title)}\nfunction toast(m,t=2200){const e=$('#toast');if(!e)return;e.textContent=m;e.style.display='block';clearTimeout(toast._t);toast._t=setTimeout(()=>e.style.display='none',t)}\n\n/* ---------- maîtrise ---------- */\nfunction chMastery(cid){const qs=QBY[cid]||[];let seen=0,ok=0;qs.forEach(q=>{const s=S.qs[q.id];if(s){seen++;if(s.l)ok++}});return{seen,ok,total:qs.length,pct:qs.length?Math.round(ok/qs.length*100):0}}\nfunction mClass(cid){const m=chMastery(cid);if(!m.seen)return'';return m.pct>=80?'c-green':m.pct>=40?'c-amber':'c-red'}\nfunction mColor(cid){const c=mClass(cid);return c==='c-green'?'var(--green)':c==='c-amber'?'var(--amber)':c==='c-red'?'var(--red)':'var(--grey)'}\nfunction mastered(){return DATA.chapters.filter(c=>chMastery(c.id).pct>=80).length}\nfunction ring(pct,col){const r=19,C=2*Math.PI*r;return `<svg class=\"ring\" viewBox=\"0 0 46 46\"><circle cx=\"23\" cy=\"23\" r=\"${r}\" fill=\"none\" style=\"stroke:var(--tint2)\" stroke-width=\"6\"/><circle cx=\"23\" cy=\"23\" r=\"${r}\" fill=\"none\" stroke=\"${col}\" stroke-width=\"6\" stroke-linecap=\"round\" stroke-dasharray=\"${C}\" stroke-dashoffset=\"${C*(1-pct/100)}\" transform=\"rotate(-90 23 23)\"/><text x=\"23\" y=\"27\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" style=\"fill:var(--ink)\">${pct}%</text></svg>`}\nfunction answerText(q){if(q.type==='saisie')return(q.answer||[''])[0];if(q.type==='vf')return q.answer===0?Tx('quiz.true','Vrai'):Tx('quiz.false','Faux');if(Array.isArray(q.answer))return q.answer.map(i=>q.options[i]).join(' · ');return(q.options||[])[q.answer]}\nfunction buildCards(){CARDS=[];\n DATA.questions.forEach(q=>{CARDS.push({id:'q'+q.id,ch:q.ch,front:(q.scen?esc(q.scen)+'<br><br>':'')+esc(q.q)+(q.type==='vf'?'<br><small>'+Tx('flash.vfhint','(Vrai ou faux ?)')+'</small>':''),back:answerText(q),exp:q.exp||q.snip||'',img:q.img||null,src:q.src,page:q.page})});\n DATA.glossary.forEach((g,i)=>CARDS.push({id:'g'+i,ch:g.ch,front:Tx('flash.define','Définis :')+' <b>'+esc(g.t)+'</b>',back:g.d,exp:'',src:chOf(g.ch).part,page:null}));\n DATA.numbers.forEach((n,i)=>CARDS.push({id:'n'+i,ch:n.ch,front:Tx('flash.number','Quel chiffre ?')+' <br><b>'+esc(n.l)+'</b>',back:n.v,exp:'',src:chOf(n.ch).part,page:null}))}\n\n/* ---------- écrans, blocs, mise en page ---------- */\nconst BLK={}, AFTER={};\nfunction B(id,label,html,o){BLK[id]=Object.assign({id,label,html,portable:true},o||{})}\nlet VIEW='home',VSTACK=[],ctx={};\nconst SIG=()=>T('meta.signature',META.signature);\nfunction header(where){return `<header class=\"hdr\"><h1 class=\"brand\"><span class=\"b1\">${T('meta.brand1',esc(META.brand[0]||''))}</span> <span class=\"b2\">${T('meta.brand2',esc(META.brand[1]||''))}</span></h1><div class=\"sub\">${T('meta.subtitle',esc(META.subtitle||''))}</div><div class=\"sig\">${SIG()}</div><div class=\"where\">${where}</div></header>`}\nfunction miniHeader(small,title,backHtml){return `<header class=\"hdr mini\">${backHtml||`<button class=\"back\" onclick=\"back()\">${Tx('ui.back','← Retour')}</button>`}<div class=\"tt\"><small>${small}</small><div>${title}</div><div class=\"sig mini\">${SIG()}</div></div></header>`}\nconst FOOT=()=>`<div class=\"foot\">${SIG()}</div>`;\nconst SCREENS={\n home:{n:'Accueil',main:1,hdr:()=>header(T('home.where','Accueil')),blocks:['home.hello','home.boss','home.resume','home.search','home.launch','home.flashlaunch','home.prepa','home.progress','home.grid']},\n chapters:{n:'Chapitres',main:1,hdr:()=>header(T('chapters.where','Chapitres')),blocks:['chapters.list']},\n revise:{n:'Réviser',main:1,hdr:()=>header(T('revise.where','Réviser')),blocks:['revise.buttons','revise.grid','revise.campaign']},\n stats:{n:'Statistiques',main:1,hdr:()=>header(T('stats.where','Statistiques')),blocks:['stats.kpis','stats.mastery','stats.types','stats.weak','stats.hist']},\n profile:{n:'Profil',main:1,hdr:()=>header(T('profile.where','Profil')),blocks:['profile.identity','profile.badges','profile.colors','profile.hl','profile.data']},\n campaign:{n:'Campagne & boss',hdr:()=>miniHeader(T('campaign.small','Campagne'),T('campaign.title','⚔️ Campagne & boss')),blocks:['campaign.intro','campaign.list']},\n numbers:{n:'Chiffres clés',hdr:()=>miniHeader(T('numbers.small','Données à retenir'),T('numbers.title','🔢 Chiffres clés')),blocks:['numbers.list']},\n glossary:{n:'Glossaire',hdr:()=>miniHeader(T('glossary.small','Vocabulaire'),T('glossary.title','🔤 Glossaire')),blocks:['glossary.list']},\n course:{n:'Sommaire & cours',hdr:()=>miniHeader(T('course.small','Sommaire'),T('course.title','📖 Sommaire & cours')),blocks:['course.list']},\n images:{n:'Images & schémas',hdr:()=>miniHeader(T('images.small','Planches des PDF'),T('images.title','🖼️ Images & schémas')),blocks:['images.gallery']},\n resumes:{n:'Résumés & tableaux',hdr:()=>miniHeader(T('resumes.small','Résumés de cours & tableaux'),T('resumes.title','📋 Résumés & tableaux')),blocks:['resumes.main']},\n chapter:{n:'Fiche chapitre',ctx:1,hdr:()=>{const c=chOf(ctx.id);return miniHeader(esc(chOf(c.id)&&PARTM[c.part]?PARTM[c.part].name:'')+' · p.'+c.pages[0]+'–'+c.pages[1],c.emo+' '+esc(c.title))},blocks:['chapter.mastery','chapter.quizbtn','chapter.grid','chapter.resume','chapter.tables']},\n reader:{n:'Lecture du cours',ctx:1,hdr:()=>{const c=chOf(ctx.ch);return miniHeader(T('reader.small','Cours')+' · '+esc((PARTM[c.part]||{}).name||''),c.emo+' '+esc(c.title))},blocks:['reader.main']},\n source:{n:'Page source',ctx:1,hdr:()=>{const p=curSource();const c=chOf(p.ch);return miniHeader(T('source.small','Page source')+' · '+esc(srcName(p.src)),c.emo+' '+esc(c.title))},blocks:['source.main']},\n quiz:{n:'Quiz',ctx:1,nonav:1,hdr:()=>{const q=curQ();return miniHeader((QZ.boss!=null?T('quiz.bossmode','⚔️ Combat de boss'):T('quiz.mode','Quiz'))+' · '+esc(QZ.label||''),chOf(q.ch).emo+' '+esc(chOf(q.ch).title),`<button class=\"back\" onclick=\"quitQuiz()\">${Tx('quiz.quit','✕ Quitter')}</button>`)},blocks:['quiz.main']},\n exam:{n:'Examen blanc',ctx:1,nonav:1,hdr:()=>miniHeader(T('exam.small','📝 Examen blanc')+' · <span class=\"timer\" id=\"tmr\"></span>',T('exam.qnum','Question {i}/{n}',{i:EX.idx+1,n:EX.ids.length}),`<button class=\"back\" onclick=\"if(confirm('${jsq(Tx('exam.abandon','Abandonner l’examen ?'))}'))tab('home')\">✕</button>`),blocks:['exam.main']},\n result:{n:'Résultat',ctx:1,hdr:()=>header(T('result.where','Résultat')),blocks:['result.score','result.review','result.actions']},\n prepa:{n:'Prépa Examen D.E',hdr:()=>miniHeader(T('prepa.small','Questions d’examen corrigées avec les cours'),T('prepa.title','🎓 Prépa Examen D.E')),blocks:['prepa.intro','prepa.series','prepa.types','prepa.edit','prepa.hors']},\n config:{n:'Lancer le quiz',ctx:1,hdr:()=>miniHeader(T('config.small','Réviser'),T('config.title','🎯 Lancer le quiz')),blocks:['config.subjects','config.main']},\n flashcfg:{n:'Réglage flashcards',ctx:1,hdr:()=>miniHeader(T('flashcfg.small','Réviser'),T('flashcfg.title','🃏 Flashcards')),blocks:['flashcfg.leitner','flashcfg.main']},\n flash:{n:'Flashcards',ctx:1,hdr:()=>FL&&FL.i<FL.deck.length?miniHeader(T('flash.small','Flashcards')+' · '+esc(chOf(FL.deck[FL.i].ch).short),T('flash.cardnum','Fiche {i}/{n} · boîte {b}',{i:FL.i+1,n:FL.deck.length,b:((S.lt[FL.deck[FL.i].id]||{b:0}).b)+1})):miniHeader(T('flash.small','Flashcards'),T('flash.done','Session terminée')),blocks:['flash.main']}};\nconst MENU_DEF=[{v:'home',i:'🏠',l:'Accueil'},{v:'chapters',i:'📚',l:'Chapitres'},{v:'revise',i:'🎯',l:'Réviser'},{v:'stats',i:'📈',l:'Stats'},{v:'profile',i:'👤',l:'Profil'}];\nfunction menu(){return Array.isArray(E.menu)&&E.menu.length?E.menu:MENU_DEF}\nfunction buildNav(){const n=$('#nav');if(!n)return;n.innerHTML=menu().map(m=>`<button data-v=\"${esc(m.v)}\"><span class=\"i\">${esc(m.i)}</span><span class=\"nl\">${esc(m.l)}</span></button>`).join('');$$('#nav button').forEach(b=>b.onclick=()=>tab(b.dataset.v))}\nfunction layoutOf(sc){const l=E.layout&&E.layout[sc];if(Array.isArray(l))return l;return((SCREENS[sc]||{}).blocks||[]).map(id=>({id,inst:id}))}\nfunction bstyle(b,d){let s='--ts:'+(b.ts||1)+';';if(d.grid)s+='--cols:'+(b.cols||2)+';';else if(b.bs&&b.bs!==1)s+='zoom:'+b.bs+';';return s}\nfunction go(v,c={},push=true){if(push&&VIEW)VSTACK.push({v:VIEW,c:ctx,y:window.scrollY});VIEW=v;ctx=c;render();window.scrollTo(0,c.y||0)}\nfunction back(){const p=VSTACK.pop();if(!p){go('home',{},false);return}VIEW=p.v;ctx=p.c;render();setTimeout(()=>window.scrollTo(0,p.y||0),0)}\nfunction tab(v){VSTACK=[];go(v,{},false)}\nfunction render(){const sc=SCREENS[VIEW]?VIEW:'home';if(sc!==VIEW)VIEW=sc;const spec=SCREENS[sc];\n const root=VSTACK.length?VSTACK[0].v:VIEW;$$('#nav button').forEach(b=>b.classList.toggle('on',b.dataset.v===VIEW||b.dataset.v===root));\n const nav=$('#nav');if(nav)nav.classList.toggle('hide',!!spec.nonav);\n const present=[];\n const body=layoutOf(sc).map(b=>{const d=BLK[b.id];if(!d)return'';if(b.hidden&&!EDITMODE)return'';let h='';try{h=d.html()||''}catch(e){console.error(b.id,e);h=''}\n  if(!h&&!EDITMODE)return'';if(!present.includes(d))present.push(d);\n  return `<section class=\"blk${b.hidden?' blk-hid':''}\" data-inst=\"${esc(b.inst)}\" data-bid=\"${esc(b.id)}\" style=\"${bstyle(b,d)}\">${h||'<div class=\"emptyblk\">'+esc(d.label)+' — vide ici</div>'}</section>`}).join('');\n let hd='';try{hd=spec.hdr()}catch(e){console.error(e);hd=header('')}\n $('#app').innerHTML=hd+'<div class=\"wrap\">'+body+FOOT()+'</div>';\n present.forEach(d=>{if(d.after)try{d.after()}catch(e){console.error(d.id,e)}});\n if(AFTER[sc])try{AFTER[sc]()}catch(e){console.error(e)}\n if(window.PORTAIL_EDITOR&&!RO)window.PORTAIL_EDITOR.decorate(sc)}\n/* grille de tuiles réordonnables */\nfunction grid(gid,tiles){const ord=E.tiles&&E.tiles[gid];let list=tiles.slice();\n if(Array.isArray(ord)){const m={};tiles.forEach(t=>m[t.id]=t);list=ord.filter(o=>m[o.id]).map(o=>Object.assign({},m[o.id],{hidden:!!o.hidden}));tiles.forEach(t=>{if(!ord.some(o=>o.id===t.id))list.push(t)})}\n return `<div class=\"grid\" data-grid=\"${gid}\">${list.filter(t=>t.show!==false&&(!t.hidden||EDITMODE)).map(t=>`<button class=\"tile${t.hidden?' tile-hid':''}\" data-tile=\"${t.id}\" style=\"--tc:${t.c}\" onclick=\"${t.on}\"><span class=\"e\">${t.e}</span><span><span class=\"l\" style=\"display:block\">${t.l}</span><span class=\"n\" style=\"display:block\">${t.n}</span></span></button>`).join('')}</div>`}\nfunction tileList(gid,tiles){return tiles}\n\n/* ======================= ACCUEIL ======================= */\nfunction nextBoss(){return DATA.bosses.findIndex((b,i)=>!S.bosses[i])}\nB('home.hello','Carte de bienvenue',()=>{const L=level();return `<div class=\"card hello\"><div class=\"ava\">${S.avatar}</div><div style=\"flex:1\"><div class=\"nm\">${T('home.hello','Bonjour {name} !',{name:esc(S.name||Tx('home.anon','futur(e) soignant(e)'))})}</div><div class=\"lv\">${T('home.level','NIV. {n} · {name} · {xp} XP',{n:L.n,name:esc(L.name),xp:S.xp})}</div><div class=\"small\" style=\"opacity:.9\">${T('home.counters','🔥 {streak} jour(s) · {mastered}/{chapters} maîtrisés · {boss}/{bosses} boss',{streak:S.streak.count,mastered:mastered(),chapters:DATA.chapters.length,boss:Object.keys(S.bosses).length,bosses:DATA.bosses.length})}</div><div class=\"bar\"><i style=\"width:${L.pct}%\"></i></div></div></div>`});\nB('home.boss','Prochain boss',()=>{if(!DATA.bosses.length)return'';const nb=nextBoss(),b=DATA.bosses[nb];\n if(!b)return `<div class=\"card boss\"><div class=\"be\">🏆</div><div><div class=\"bn\">${T('home.boss.done','Campagne terminée !')}</div><div class=\"bt\">${T('home.boss.donesub','Tous les boss sont vaincus. Bravo !')}</div></div></div>`;\n return `<div class=\"card boss\" onclick=\"startBoss(${nb})\"><div class=\"be\">${b.emo}</div><div><div class=\"bt\">${T('home.boss.lvl','Niveau {n} · {lvl}',{n:nb+1,lvl:esc(b.lvl||'')})}</div><div class=\"bn\">${T('home.boss.fight','⚔️ Affronter {name}',{name:esc(b.name)})}</div><div class=\"bt\">${T('home.boss.sub','Bats-le pour passer au niveau {next} · {chs}',{next:nb+2,chs:b.chs.map(c=>esc(chOf(c).short)).join(', ')})}</div></div></div>`});\nB('home.resume','Reprendre le quiz',()=>{const sv=S.save&&S.save.ids&&S.save.idx<S.save.ids.length;return sv?`<button class=\"btn\" onclick=\"resumeQuiz()\">${T('home.resume','▶ Reprendre le quiz ({i}/{n})',{i:S.save.idx,n:S.save.ids.length})}</button>`:''});\nB('home.search','Recherche',()=>`<div class=\"card\" style=\"padding:12px\"><div class=\"search\">🔍<input class=\"srch\" placeholder=\"${esc(Tx('home.search.ph','Rechercher dans le cours, les questions, le glossaire…'))}\" autocomplete=\"off\"></div><div class=\"sout\"></div></div>`,{after:()=>$$('.srch').forEach(i=>i.oninput=()=>doSearch(i))});\nB('home.launch','Carte « Lancer le quiz »',()=>`<div class=\"card launch\" onclick=\"go('config')\"><svg width=\"86\" height=\"80\" viewBox=\"0 0 86 80\"><path d=\"M8 70 L40 8 L72 70 Z\" style=\"fill:var(--h1)\"/><path d=\"M20 47 H60 M14 59 H66\" stroke=\"#FFC24B\" stroke-width=\"4\"/><rect x=\"58\" y=\"6\" width=\"14\" height=\"44\" rx=\"7\" fill=\"#fff\" style=\"stroke:var(--h1)\" stroke-width=\"4\"/><rect x=\"62\" y=\"22\" width=\"6\" height=\"24\" rx=\"3\" fill=\"#FFE08A\"/><path d=\"M4 76 L26 66 L44 72 L64 58 L82 62\" stroke=\"#FFE08A\" stroke-width=\"5\" fill=\"none\" stroke-linecap=\"round\"/></svg><div><div class=\"t\">${T('home.launch.t','Lancer le quiz')}</div><div class=\"s\">${T('home.launch.s','{n} questions · {c} fiches',{n:DATA.questions.length,c:CARDS.length})}</div></div></div>`);\n/* ======================= PRÉPA EXAMEN D.E ======================= */\nfunction PREPA(){const p=DATA.prepa||{};return {q:p.q||[],hors:p.hors||[],title:p.title||'',size:p.size||50}}\nfunction prepaIds(f){return PREPA().q.filter(q=>!f||f(q)).map(q=>q.id)}\nfunction prepaSeries(){const P=PREPA(),out=[];const L=P.q.slice().sort((a,b)=>(a.num||0)-(b.num||0));for(let i=0;i<L.length;i+=P.size)out.push(L.slice(i,i+P.size));return out}\nfunction startPrepa(ids,label,k){if(!ids.length){toast(Tx('toast.noq','Aucune question pour ces critères'));return}startQuiz(ids,label,k!=null?{subj:'prepa'+k}:{})}\nB('home.prepa','Carte « Prépa Examen D.E »',()=>PREPA().q.length?`<div class=\"card launch\" style=\"background:linear-gradient(135deg,var(--plum1,#5b2a86),var(--plum2,#8e3b8a))\" onclick=\"go('prepa')\"><div class=\"ic\" style=\"font-size:42px\">🎓</div><div><div class=\"t\">${T('home.prepa.t','Prépa Examen D.E')}</div><div class=\"s\">${T('home.prepa.s','{n} questions d’examen corrigées · page source',{n:PREPA().q.length})}</div></div></div>`:'');\nB('prepa.intro','Présentation et lancement',()=>{const P=PREPA();const seen=P.q.filter(q=>S.qs[q.id]).length,ok=P.q.filter(q=>S.qs[q.id]&&S.qs[q.id].l).length,err=P.q.filter(q=>S.qs[q.id]&&!S.qs[q.id].l).length;\n return `<div class=\"card\"><h3>${T('prepa.h','🎓 Prépa Examen D.E')}</h3>${P.title?`<div class=\"small muted\" style=\"margin-bottom:6px\">${esc(P.title)}</div>`:''}<div class=\"small\">${T('prepa.desc','{n} questions corrigées uniquement à partir des cours fournis, avec explication et page source.',{n:P.q.length})}${P.hors.length?' '+T('prepa.desc.hors','{m} question(s) non traitée(s) par les cours sont listées en bas, sans corrigé.',{m:P.hors.length}):''}</div>\n <div class=\"small muted\" style=\"margin:8px 0 12px\">${T('prepa.prog','Vues : {s}/{n} · réussies : {o} · à revoir : {e}',{s:seen,n:P.q.length,o:ok,e:err})}</div>\n <button class=\"btn coral\" onclick=\"startPrepa(shuffle(prepaIds()).slice(0,PREPA().size),'${jsq(Tx('prepa.rand.label','Prépa D.E · tirage aléatoire'))}')\">${T('prepa.rand','🎲 Sujet aléatoire ({n} questions)',{n:Math.min(P.size,P.q.length)})}</button>\n <button class=\"btn\" onclick=\"startPrepa(prepaIds(),'${jsq(Tx('prepa.all.label','Prépa D.E · toutes les questions'))}')\">${T('prepa.all','📋 Toutes les questions dans l’ordre')}</button>\n <button class=\"btn\" onclick=\"startPrepa(shuffle(prepaIds(q=>!S.qs[q.id]||!S.qs[q.id].l)),'${jsq(Tx('prepa.weak.label','Prépa D.E · à revoir'))}')\">${T('prepa.weak','🔁 Jamais vues ou à revoir ({n})',{n:P.q.length-ok})}</button></div>`},{portable:false});\nB('prepa.series','Séries numérotées',()=>{const L=prepaSeries();const st=S.subj||{};if(!L.length)return'';\n return `<div class=\"card\"><h3>${T('prepa.series.h','📝 Séries de l’épreuve')}</h3><div class=\"small muted\" style=\"margin-bottom:12px\">${T('prepa.series.sub','Les questions dans l’ordre du recueil, par séries de {n}.',{n:PREPA().size})}</div><div style=\"display:grid;grid-template-columns:repeat(var(--cols,2),minmax(0,1fr));gap:10px\">${L.map((ids,k)=>{const o=st['prepa'+k];const pct=o?Math.round(o.best/o.n*100):null;\n return `<div class=\"tile\" style=\"min-height:92px;padding:14px\" onclick=\"startPrepa(prepaSeries()[${k}].map(q=>q.id),'${jsq(Tx('prepa.serie.label','Prépa D.E · série {k}',{k:k+1}))}',${k})\"><div style=\"font-weight:800;font-size:calc(16px*var(--ts,1))\">${T('prepa.serie','Série {k}',{k:k+1})}</div><div class=\"small muted\">${T('prepa.serie.n','Questions {a} à {b}',{a:ids[0].num,b:ids[ids.length-1].num})}</div><div class=\"small\" style=\"font-weight:700;color:${pct==null?'var(--grey)':pct>=50?'var(--green)':'var(--red)'}\">${pct==null?T('prepa.todo','À faire'):T('prepa.best','Meilleur : {s}/{n} ({p} %)',{s:o.best,n:o.n,p:pct})}</div></div>`}).join('')}</div></div>`},{portable:false});\nB('prepa.types','Par type de question',()=>{const P=PREPA();const TT=TYPES.filter(t=>P.q.some(q=>q.type===t));if(!TT.length)return'';\n return `<div class=\"card\"><h3>${T('prepa.types.h','🧩 Par type de question')}</h3><div class=\"chips\">${TT.map(t=>`<span class=\"chip\" onclick=\"startPrepa(shuffle(prepaIds(q=>q.type==='${t}')),'${jsq(Tx('prepa.type.label','Prépa D.E'))} · ${jsq(typeLabel(t))}')\">${esc(typeLabel(t))} (${P.q.filter(q=>q.type===t).length})</span>`).join('')}</div></div>`},{portable:false});\nB('prepa.edit','Modifier les questions Prépa (mode édition)',()=>{if(!EDITMODE||!window.PORTAIL_EDITOR)return'';const P=PREPA();const all=P.q.concat(P.hors).sort((a,b)=>(a.num||0)-(b.num||0));\n return `<div class=\"card\"><h3>✏️ Corriger / modifier les questions</h3><div class=\"small muted\" style=\"margin-bottom:8px\">Choisis une question pour modifier l’énoncé, les propositions, la bonne réponse, l’explication et la page. Une question « hors cours » qui reçoit une réponse passe automatiquement dans les sujets.</div><input class=\"tin\" id=\"pqSearch\" placeholder=\"Chercher (numéro ou mot)…\" oninput=\"window.PQF=this.value;document.querySelectorAll('#pqList [data-pq]').forEach(r=>{const v=nrm(this.value);r.style.display=!v||nrm(r.dataset.s).includes(v)?'':'none'})\" value=\"${esc(window.PQF||'')}\"><div id=\"pqList\" style=\"max-height:420px;overflow:auto;margin-top:8px\">${all.map(q=>`<div class=\"rv\" data-pq=\"${esc(q.id)}\" data-s=\"${esc('q'+q.num+' '+q.q)}\" style=\"display:flex;gap:8px;align-items:center\"><div style=\"flex:1\"><b>Q${q.num}</b> ${q.hors?'<span class=\"small\" style=\"color:var(--red)\">· hors cours</span> ':''}${esc(q.q.length>110?q.q.slice(0,110)+'…':q.q)}</div><button class=\"chip\" onclick=\"PORTAIL_EDITOR.pqForm('${jsq(q.id)}')\">✏️</button></div>`).join('')}</div></div>`},{portable:false});\nB('prepa.hors','Questions hors des cours fournis',()=>{const H=PREPA().hors;if(!H.length)return'';\n return `<div class=\"card\"><details><summary style=\"cursor:pointer;font-weight:800;font-size:calc(17px*var(--ts,1))\">${T('prepa.hors.h','📎 Hors des cours fournis ({n})',{n:H.length})}</summary><div class=\"small muted\" style=\"margin:8px 0\">${T('prepa.hors.sub','Ces questions du recueil ne sont pas traitées dans les cours de l’appli : aucun corrigé n’est proposé pour ne rien inventer.')}</div>${H.map(h=>`<div class=\"rv\"><div><b>Q${h.num}.</b> ${esc(h.q)}</div>${(h.options||[]).length?`<div class=\"small muted\">${h.options.map((o,i)=>'ABCDEFGH'[i]+'. '+esc(o)).join(' · ')}</div>`:''}${h.why?`<div class=\"small\" style=\"color:var(--grey)\">${esc(h.why)}</div>`:''}${EDITMODE&&window.PORTAIL_EDITOR?`<button class=\"chip\" style=\"margin-top:6px\" onclick=\"PORTAIL_EDITOR.pqForm('${jsq(h.id)}')\">✏️ Corriger</button>`:''}</div>`).join('')}</details></div>`},{portable:false});\nB('home.flashlaunch','Carte « Lancer les flashcards »',()=>`<div class=\"card launch fl\" onclick=\"go('flashcfg')\"><div class=\"ic\">🃏</div><div><div class=\"t\">${T('home.flash.t','Lancer les flashcards')}</div><div class=\"s\">${T('home.flash.s','{c} fiches · système de Leitner',{c:CARDS.length})}</div></div></div>`);\nB('home.progress','Progression par partie',()=>`<div class=\"card prog\"><h3>${T('home.prog.title','Progression par partie')}</h3>${PARTS.map(p=>{const chs=DATA.chapters.filter(c=>c.part===p.id);return `<div class=\"row\"><span class=\"tag\">${esc(p.tag||p.id)}</span>${esc(p.name)} · ${T('home.prog.nch','{n} chapitres',{n:chs.length})}</div><div class=\"segs\">${chs.map(c=>`<span class=\"${mClass(c.id)}\" title=\"${esc(c.title)}\" onclick=\"go('chapter',{id:'${jsq(c.id)}'})\"></span>`).join('')}</div>`}).join('')}<div class=\"small muted\" style=\"margin-top:10px\">${T('home.prog.legend','Gris : non commencé · rouge &lt; 40 % · ambre 40-79 % · vert ≥ 80 %')}</div></div>`);\nB('home.grid','Grille de raccourcis',()=>{const nQ=DATA.questions.length,cnt=t=>DATA.questions.filter(q=>q.type===t).length;return grid('home.grid',[\n {id:'campaign',e:'⚔️',l:T('home.t.campaign','Campagne & boss'),n:T('home.t.campaign.n','{n} boss',{n:DATA.bosses.length}),on:\"go('campaign')\",c:'#EDE4FF',show:DATA.bosses.length>0},\n {id:'numbers',e:'🔢',l:T('home.t.numbers','Chiffres clés'),n:T('home.t.numbers.n','{n} données',{n:DATA.numbers.length}),on:\"go('numbers')\",c:'#FFE3DC',show:DATA.numbers.length>0},\n {id:'course',e:'📖',l:T('home.t.course','Sommaire & cours'),n:T('home.t.course.n','{n} pages',{n:DATA.course.length}),on:\"go('course')\",c:'#DFF3F0'},\n {id:'resumes',e:'📋',l:T('home.t.resumes','Résumés & tableaux'),n:T('home.t.resumes.n','Anatomie · physio · comparatifs'),on:\"go('resumes')\",c:'#FFF1CC'},\n {id:'quiz',e:'🎯',l:T('home.t.quiz','Quiz'),n:T('home.t.quiz.n','{n} questions',{n:nQ}),on:\"go('config')\",c:'#FFE2F1'},\n {id:'cas',e:'🩺',l:T('home.t.cas','Cas cliniques'),n:T('home.t.cas.n','{n} cas',{n:cnt('cas')}),on:\"startQuiz(pick({types:['cas']}),'\"+jsq(Tx('home.t.cas','Cas cliniques'))+\"')\",c:'#E2EEFF',show:cnt('cas')>0},\n {id:'flash',e:'🃏',l:T('home.t.flash','Flashcards'),n:T('home.t.flash.n','{n} fiches',{n:CARDS.length}),on:\"go('flashcfg')\",c:'#DFF3F0'},\n {id:'exam',e:'📝',l:T('home.t.exam','Examen blanc'),n:T('home.t.exam.n','{n} questions · {m} min',{n:META.exam.n,m:META.exam.min}),on:'startExam()',c:'#FFE3DC'},\n {id:'glossary',e:'🔤',l:T('home.t.glossary','Glossaire'),n:T('home.t.glossary.n','{n} termes',{n:DATA.glossary.length}),on:\"go('glossary')\",c:'#EDE4FF',show:DATA.glossary.length>0},\n {id:'images',e:'🖼️',l:T('home.t.images','Images & schémas'),n:T('home.t.images.n','{n} planches',{n:DATA.images.length}),on:\"go('images')\",c:'#FFF1CC',show:DATA.images.length>0},\n {id:'errors',e:'❌',l:T('home.t.errors','Mes erreurs'),n:T('home.t.errors.n','{n} à revoir',{n:errorIds().length}),on:'startErrors()',c:'#FDECEC'},\n {id:'new',e:'🆕',l:T('home.t.new','Jamais vues'),n:T('home.t.new.n','{n} questions pas encore traitées',{n:DATA.questions.filter(q=>!S.qs[q.id]).length}),on:\"startQuiz(pick({mode:'new',n:20}),'\"+jsq(Tx('home.t.new','Jamais vues'))+\"')\",c:'#E2EEFF'}])},{grid:1});\nfunction nrm(s){return String(s).toLowerCase().normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').replace(/[’']/g,\"'\")}\nfunction doSearch(inp){const o=inp.closest('.card').querySelector('.sout');const v=nrm(inp.value.trim());if(v.length<3){o.innerHTML='';return}\n const res=[];\n DATA.questions.forEach(q=>{if(nrm(q.q+' '+(q.scen||'')+' '+chOf(q.ch).title).includes(v))res.push([Tx('search.question','Question'),esc(q.q),()=>showQDetail(q,o)])});\n DATA.glossary.forEach(g=>{if(nrm(g.t+' '+g.d).includes(v))res.push([Tx('search.glossary','Glossaire'),'<b>'+esc(g.t)+'</b> : '+esc(g.d),null])});\n DATA.course.forEach(p=>{const t=p.html.replace(/<[^>]+>/g,' ');const k=nrm(t).indexOf(v);if(k>=0){const s=t.substr(Math.max(0,k-40),120);res.push([Tx('search.course','Cours')+' · '+srcName(p.src)+' p.'+p.page,'…'+esc(s)+'…',()=>openSource(p.src,p.page)])}});\n o.innerHTML=res.length?`<div class=\"small muted\" style=\"margin-top:8px\">${T('search.count','{n} résultat(s)',{n:res.length})}</div>`+res.slice(0,40).map((r,i)=>`<div class=\"sres\" data-i=\"${i}\"><small>${esc(r[0])}</small><div>${r[1]}</div></div>`).join(''):`<div class=\"small muted\" style=\"margin-top:8px\">${T('search.none','Aucun résultat')}</div>`;\n $$('.sres',o).forEach(e=>{const r=res[+e.dataset.i];if(r[2])e.onclick=r[2]})}\nfunction showQDetail(q,o){o.innerHTML=`<div class=\"fb good\" style=\"margin-top:10px\"><div class=\"small\"><b>${esc(chOf(q.ch).title)}</b> · ${esc(typeLabel(q.type))}</div>${q.scen?'<div class=\"scen\">'+esc(q.scen)+'</div>':''}<div style=\"font-weight:700;margin:6px 0\">${esc(q.q)}</div><div class=\"h\">✅ ${esc(answerText(q))}</div>${q.exp?'<div>'+esc(q.exp)+'</div>':''}${q.snip?'<div class=\"src\">« '+esc(q.snip)+' »</div>':''}${q.page?`<button class=\"linkbtn\" onclick=\"openSource('${jsq(q.src)}',${+q.page})\">${T('ui.srcpage','📖 Page source p.{p}',{p:q.page})}</button>`:''}</div>`}\n\n/* ======================= CHAPITRES ======================= */\nB('chapters.list','Liste des chapitres',()=>PARTS.map(p=>`<div class=\"secT\">${esc(p.emo||'📘')} ${esc(p.name)}</div>`+DATA.chapters.filter(c=>c.part===p.id).map(chRow).join('')).join(''));\nfunction chRow(c){const m=chMastery(c.id);return `<div class=\"chl\" onclick=\"go('chapter',{id:'${jsq(c.id)}'})\"><div class=\"em\">${c.emo}</div><div class=\"tx\"><b>${esc(c.id)} · ${esc(c.title)}</b><small>${T('chapters.row','{q} questions · {p} pages · vues {s}/{q}',{q:m.total,p:(COURSE_BY[c.id]||[]).length,s:m.seen})}</small></div>${ring(m.pct,mColor(c.id))}</div>`}\nB('chapter.mastery','Maîtrise du chapitre',()=>{const m=chMastery(ctx.id);return `<div class=\"card\" style=\"display:flex;gap:14px;align-items:center\">${ring(m.pct,mColor(ctx.id))}<div><b>${T('chapter.mastery','Maîtrise {p} %',{p:m.pct})}</b><div class=\"small muted\">${T('chapter.mastery.sub','{ok} réussies sur {t} · {s} vues',{ok:m.ok,t:m.total,s:m.seen})}</div></div></div>`},{portable:false});\nB('chapter.quizbtn','Bouton quiz du chapitre',()=>{const c=chOf(ctx.id);return `<button class=\"btn coral\" onclick=\"startQuiz(pick({chs:['${jsq(c.id)}']}),'${jsq(c.short)}')\">${T('chapter.quiz','🎯 Quiz du chapitre ({n})',{n:(QBY[c.id]||[]).length})}</button>`},{portable:false});\nB('chapter.grid','Raccourcis du chapitre',()=>{const c=chOf(ctx.id),id=jsq(c.id);return grid('chapter.grid',[\n {id:'read',e:'📖',l:T('chapter.t.read','Lire le cours'),n:T('chapter.t.read.n','{n} pages',{n:(COURSE_BY[c.id]||[]).length}),on:`go('reader',{ch:'${id}'})`,c:'#DFF3F0'},\n {id:'flash',e:'🃏',l:T('chapter.t.flash','Flashcards'),n:T('chapter.t.flash.n','{n} fiches',{n:CARDS.filter(k=>k.ch===c.id).length}),on:`startFlash(['${id}'])`,c:'#FFF1CC'},\n {id:'errors',e:'❌',l:T('chapter.t.errors','Erreurs'),n:T('chapter.t.errors.n','{n} à revoir',{n:errorIds([c.id]).length}),on:`startErrors(['${id}'])`,c:'#FDECEC'},\n {id:'images',e:'🖼️',l:T('chapter.t.images','Schémas'),n:T('chapter.t.images.n','{n} planches',{n:DATA.images.filter(i=>i.ch===c.id).length}),on:`go('images',{f:'${id}'})`,c:'#EDE4FF'}])},{portable:false,grid:1});\nB('chapter.resume','Résumé du chapitre',()=>{const ra=DATA.resAnat[ctx.id]||[];return ra.length?`<div class=\"card res\"><div class=\"rh\">${T('chapter.resume','📌 Résumé du chapitre')}</div><ul>${ra.map(x=>'<li>'+x+'</li>').join('')}</ul></div>`:''},{portable:false});\nB('chapter.tables','Physiologie & tableaux du chapitre',()=>{const id=ctx.id;return DATA.resPhysio.filter(t=>t.ch===id).map(physioCard).join('')+DATA.tabRes.filter(t=>t.ch===id).map(t=>tableCard(t,'📋')).join('')+DATA.tabComp.filter(t=>t.ch===id).map(t=>tableCard(t,'⚖️')).join('')},{portable:false});\nfunction pill(ch){const c=chOf(ch);return `<span class=\"pill ${partIdx(c.part)%2?'a':''}\">${esc(c.short)}</span>`}\nfunction tableCard(t,ic){return `<div class=\"card\"><div class=\"rh\">${ic} ${esc(t.t)} ${pill(t.ch)}</div><div class=\"tw\"><table><tr>${t.head.map(h=>'<th>'+esc(h)+'</th>').join('')}</tr>${t.rows.map(r=>'<tr>'+r.map(x=>'<td>'+esc(x)+'</td>').join('')+'</tr>').join('')}</table></div></div>`}\nfunction physioCard(p){return `<div class=\"card res\"><div class=\"rh\">⚙️ ${esc(p.t)} ${pill(p.ch)}</div><ul>${p.items.map(x=>'<li>'+esc(x)+'</li>').join('')}</ul></div>`}\n\n/* ======================= COURS ======================= */\nB('course.list','Sommaire du cours',()=>PARTS.map(p=>`<div class=\"secT\">${esc(p.name)}</div>`+DATA.chapters.filter(c=>c.part===p.id).map(c=>{const pg=COURSE_BY[c.id]||[];const rd=pg.filter(x=>S.read[PAGEKEY(x)]).length;return `<div class=\"chl\" onclick=\"go('reader',{ch:'${jsq(c.id)}'})\"><div class=\"em\">${c.emo}</div><div class=\"tx\"><b>${esc(c.title)}</b><small>${T('course.row','p.{a}–{b} · {n} pages · lues {r}/{n}',{a:c.pages[0],b:c.pages[1],n:pg.length,r:rd})}</small></div><span style=\"font-size:22px\">›</span></div>`}).join('')).join(''));\nfunction pageHTML(p){const k=PAGEKEY(p);const body=(!EDITMODE&&S.ann[k])||p.html;const imgs=p.imgs.filter(id=>IMG[id]&&IMGI[id]).map(id=>`<img src=\"${IMG[id]}\" alt=\"\" onclick=\"openLB('${jsq(id)}')\"><div class=\"cap\">🖼️ ${esc(IMGI[id].cap)}</div>`).join('');\n return `<div class=\"pg\" id=\"pg-${esc(k)}\"><div class=\"pgh\"><span class=\"pbadge\">${esc(srcName(p.src))} · p.${p.page}</span></div>${imgs?'<div class=\"pgc\">'+imgs+'</div>':''}<div class=\"pgc\" data-k=\"${esc(k)}\">${body}</div></div>`}\nB('reader.main','Lecture du chapitre',()=>{const c=chOf(ctx.ch);const pg=COURSE_BY[c.id]||[];pg.forEach(p=>S.read[PAGEKEY(p)]=1);save();\n const i=DATA.chapters.indexOf(c),prev=DATA.chapters[i-1],next=DATA.chapters[i+1];\n return `${annotBar()}${pg.map(p=>pageHTML(p)).join('')}<button class=\"btn coral\" onclick=\"startQuiz(pick({chs:['${jsq(c.id)}']}),'${jsq(c.short)}')\">${T('reader.test','🎯 Me tester sur ce chapitre')}</button>\n <div style=\"display:flex;gap:10px\">${prev?`<button class=\"btn light\" onclick=\"go('reader',{ch:'${jsq(prev.id)}'},false)\">‹ ${esc(prev.short)}</button>`:''}${next?`<button class=\"btn light\" onclick=\"go('reader',{ch:'${jsq(next.id)}'},false)\">${esc(next.short)} ›</button>`:''}</div>`},{portable:false,after:()=>{bindAnnot();if(ctx.scrollTo){const e=document.getElementById('pg-'+ctx.scrollTo);if(e)setTimeout(()=>e.scrollIntoView({block:'start'}),30)}}});\nfunction hasPage(src,page){return DATA.course.some(x=>x.src===src&&x.page===+page)}\nfunction openSource(src,page){let p=DATA.course.find(x=>x.src===src&&x.page===page);if(!p){p=DATA.course.filter(x=>x.src===src&&x.page<=page).pop()||DATA.course.find(x=>x.src===src)}if(!p){toast(Tx('source.none','Page introuvable'));return}go('source',{src:p.src,page:p.page})}\nfunction curSource(){return DATA.course.find(x=>x.src===ctx.src&&x.page===ctx.page)||DATA.course[0]}\nB('source.main','Page source',()=>{const p=curSource();S.read[PAGEKEY(p)]=1;save();const c=chOf(p.ch);const list=COURSE_BY[c.id]||[p],i=list.indexOf(p);\n return `${pageHTML(p)}${annotBar()}<div style=\"display:flex;gap:10px\">${list[i-1]?`<button class=\"btn light\" onclick=\"go('source',{src:'${jsq(p.src)}',page:${list[i-1].page}},false)\">‹ p.${list[i-1].page}</button>`:''}${list[i+1]?`<button class=\"btn light\" onclick=\"go('source',{src:'${jsq(p.src)}',page:${list[i+1].page}},false)\">p.${list[i+1].page} ›</button>`:''}</div>\n <button class=\"btn\" onclick=\"go('reader',{ch:'${jsq(c.id)}',scrollTo:'${jsq(PAGEKEY(p))}'})\">${T('source.readall','📖 Lire tout le chapitre')}</button><button class=\"btn light\" onclick=\"back()\">${T('source.back','← Revenir où j’étais')}</button>`},{portable:false,after:()=>bindAnnot()});\n\n/* ---------- surligneur de l'étudiant ---------- */\nlet annotOn=true;\nfunction annotBar(){return `<div class=\"annot\"><button id=\"annBtn\" class=\"${annotOn?'on':''}\" onclick=\"annotOn=!annotOn;this.classList.toggle('on',annotOn);toast(annotOn?'${jsq(Tx('annot.on','Surligneur activé'))}':'${jsq(Tx('annot.off','Surligneur désactivé'))}')\">${T('annot.btn','✏️ Annoter')}</button><span class=\"small muted\">${T('annot.help','Sélectionne du texte pour surligner · touche un surlignage pour l’effacer')}</span></div>`}\nlet selRange=null,selBox=null;\nfunction bindAnnot(){$$('.pgc[data-k]').forEach(b=>{b.onclick=e=>{if(EDITMODE)return;const m=e.target.closest('mark.hl');if(m&&annotOn&&!window.getSelection().toString()){unwrap(m);persist(b);toast(Tx('annot.erased','Surlignage effacé'))}}})}\nfunction checkSel(){const pal=$('#palette');if(!pal)return;const sel=window.getSelection();if(EDITMODE||!annotOn||!sel.rangeCount||sel.isCollapsed){pal.style.display='none';return}\n const r=sel.getRangeAt(0);const box=(r.commonAncestorContainer.nodeType===1?r.commonAncestorContainer:r.commonAncestorContainer.parentElement).closest('.pgc[data-k]');if(!box){pal.style.display='none';return}\n selRange=r.cloneRange();selBox=box;const rc=r.getBoundingClientRect();pal.style.display='flex';\n let top=rc.top-62;if(top<70)top=rc.bottom+60;pal.style.top=Math.min(window.innerHeight-70,top)+'px';pal.style.left=Math.max(8,Math.min(window.innerWidth-220,rc.left))+'px'}\nfunction textNodesIn(range,box){const out=[];const w=document.createTreeWalker(box,NodeFilter.SHOW_TEXT);let n;while(n=w.nextNode()){if(range.intersectsNode(n)&&n.nodeValue.trim())out.push(n)}return out}\nfunction wrapRange(range,c){const nodes=textNodesIn(range,selBox);nodes.forEach(n=>{let s=0,e=n.nodeValue.length;if(n===range.startContainer)s=range.startOffset;if(n===range.endContainer)e=range.endOffset;if(e<=s)return;\n  const pm=n.parentElement.closest('mark.hl');if(pm){pm.className='hl h'+c;return}\n  const mid=n.splitText(s);mid.splitText(e-s);const m=document.createElement('mark');m.className='hl h'+c;mid.parentNode.insertBefore(m,mid);m.appendChild(mid)})}\nfunction eraseRange(range,box){$$('mark.hl',box).forEach(m=>{if(range.intersectsNode(m))unwrap(m)})}\nfunction unwrap(m){const p=m.parentNode;while(m.firstChild)p.insertBefore(m.firstChild,m);p.removeChild(m);p.normalize()}\nfunction persist(box){const k=box.dataset.k;if(!$$('mark.hl',box).length)delete S.ann[k];else S.ann[k]=box.innerHTML;save()}\n\n/* ======================= RÉSUMÉS & TABLEAUX ======================= */\nB('resumes.main','Résumés & tableaux',()=>{const t=ctx.tab||'anat',f=ctx.f||'all';\n const fil=ch=>f==='all'||f===chOf(ch).part||f===ch;let body='';\n if(t==='anat')body=DATA.chapters.filter(c=>fil(c.id)&&(DATA.resAnat[c.id]||[]).length).map(c=>`<div class=\"card res\"><div class=\"rh\">${c.emo} ${esc(c.title)} ${pill(c.id)}</div><ul>${DATA.resAnat[c.id].map(x=>'<li>'+x+'</li>').join('')}</ul><button class=\"linkbtn\" onclick=\"go('reader',{ch:'${jsq(c.id)}'})\">${T('resumes.full','📖 Cours complet')}</button></div>`).join('');\n if(t==='physio')body=DATA.resPhysio.filter(p=>fil(p.ch)).map(physioCard).join('');\n if(t==='tabRes')body=DATA.tabRes.filter(x=>fil(x.ch)).map(x=>tableCard(x,'📋')).join('');\n if(t==='tabComp')body=DATA.tabComp.filter(x=>fil(x.ch)).map(x=>tableCard(x,'⚖️')).join('');\n const TB=[['anat',T('resumes.tab.anat','📌 Résumés')],['physio',T('resumes.tab.physio','⚙️ Physiologie')],['tabRes',T('resumes.tab.tabRes','📋 Tableaux résumés')],['tabComp',T('resumes.tab.tabComp','⚖️ Comparatifs')]];\n const chOpts=DATA.chapters.map(c=>`<option value=\"${esc(c.id)}\" ${f===c.id?'selected':''}>${esc((PARTM[c.part]||{}).name||'')} · ${esc(c.title)}</option>`).join('');\n return `<div class=\"tabs\">${TB.map(x=>`<button class=\"${t===x[0]?'on':''}\" onclick=\"go('resumes',{tab:'${x[0]}',f:'${jsq(f)}'},${VIEW==='resumes'?'false':'true'})\">${x[1]}</button>`).join('')}</div>\n ${PARTS.length>1?`<div class=\"chips\" style=\"margin-bottom:10px\">${[['all',Tx('ui.all','Tout')]].concat(PARTS.map(p=>[p.id,p.name])).map(x=>`<span class=\"chip ${f===x[0]?'on':''}\" onclick=\"go('resumes',{tab:'${t}',f:'${jsq(x[0])}'},${VIEW==='resumes'?'false':'true'})\">${esc(x[1])}</span>`).join('')}</div>`:''}\n <select class=\"tin\" style=\"margin-bottom:14px\" onchange=\"go('resumes',{tab:'${t}',f:this.value||'all'},${VIEW==='resumes'?'false':'true'})\"><option value=\"\">${esc(Tx('resumes.filter','— Filtrer par chapitre —'))}</option>${chOpts}</select>\n ${body||`<div class=\"card muted\">${T('resumes.empty','Rien pour ce filtre dans cet onglet. Essaie un autre onglet.')}</div>`}`});\n\n/* ======================= MOTEUR DE QUIZ ======================= */\nfunction shuffle(a){a=a.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}\nfunction pick(o){let qs=DATA.questions;if(o.chs)qs=qs.filter(q=>o.chs.includes(q.ch));if(o.parts)qs=qs.filter(q=>o.parts.includes(chOf(q.ch).part));if(o.types)qs=qs.filter(q=>o.types.includes(q.type));\n if(o.mode==='new')qs=qs.filter(q=>!S.qs[q.id]);if(o.mode==='err')qs=qs.filter(q=>S.qs[q.id]&&!S.qs[q.id].l);if(o.mode==='weak')qs=qs.filter(q=>!S.qs[q.id]||!S.qs[q.id].l);\n qs=shuffle(qs);if(o.n&&o.n!=='all')qs=qs.slice(0,+o.n);return qs.map(q=>q.id)}\nfunction errorIds(chs){return DATA.questions.filter(q=>S.qs[q.id]&&!S.qs[q.id].l&&(!chs||chs.includes(q.ch))).map(q=>q.id)}\nfunction startErrors(chs){const ids=shuffle(errorIds(chs));if(!ids.length){toast(Tx('toast.noerrors','Aucune erreur à revoir 🎉'));return}startQuiz(ids,Tx('home.t.errors','Mes erreurs'))}\nlet QZ=null;\nfunction startQuiz(ids,label,opts={}){ids=ids.filter(id=>QI[id]);if(!ids.length){toast(Tx('toast.noq','Aucune question pour ces critères'));return}\n QZ={ids,idx:0,score:0,label,boss:opts.boss,subj:opts.subj,answers:[],ans:false,sel:[],order:{}};if(opts.boss==null){S.save={ids,idx:0,score:0,label,subj:opts.subj,answers:[]};save()}touchStreak();go('quiz')}\nfunction resumeQuiz(){const s=S.save;const ids=s.ids.filter(id=>QI[id]);QZ={ids,idx:Math.min(s.idx,ids.length-1),score:s.score,label:s.label,subj:s.subj,answers:s.answers||[],ans:false,sel:[],order:{}};go('quiz')}\nfunction curQ(){return QI[QZ.ids[QZ.idx]]}\nfunction nearImg(q){if(q.type==='img')return null;const im=DATA.images.filter(i=>i.ch===q.ch&&i.src===q.src&&IMG[i.id]);if(!im.length)return null;im.sort((a,b)=>Math.abs(a.page-q.page)-Math.abs(b.page-q.page));return Math.abs(im[0].page-q.page)<=6?im[0]:null}\nconst isMulti=q=>q.type==='qcd'||(q.type==='img'&&Array.isArray(q.answer));\nB('quiz.main','Question en cours',()=>{const q=curQ();const n=QZ.ids.length;\n if(!QZ.order[QZ.idx])QZ.order[QZ.idx]=q.type==='vf'||!q.options?(q.options||[]).map((_,i)=>i):shuffle(q.options.map((_,i)=>i));\n const ord=QZ.order[QZ.idx],L='ABCDEFGH';let opts='';\n if(q.type==='vf')opts=`<div class=\"vfrow\"><button class=\"opt\" data-i=\"0\">${T('quiz.vtrue','✔️ Vrai')}</button><button class=\"opt\" data-i=\"1\">${T('quiz.vfalse','✖️ Faux')}</button></div>`;\n else if(q.type==='saisie')opts=`<input class=\"tin\" id=\"tin\" placeholder=\"${esc(Tx('quiz.input','Ta réponse…'))}\" autocomplete=\"off\" autocapitalize=\"off\">`;\n else opts=ord.map((oi,k)=>`<button class=\"opt\" data-i=\"${oi}\"><span class=\"k\">${L[k]}</span><span>${esc(q.options[oi])}</span></button>`).join('');\n const img=q.type==='img'&&IMG[q.img]?`<img class=\"qimg\" src=\"${IMG[q.img]}\" onclick=\"openLB('${jsq(q.img)}')\"><div class=\"qimgcap\">🖼️ ${esc((IMGI[q.img]||{}).cap||'')} · p.${(IMGI[q.img]||{}).page||''}</div>`:'';\n return `<div class=\"qtop\"><span>${T('quiz.num','Question {i}/{n}',{i:QZ.idx+1,n})}</span><span>✅ ${QZ.score}</span></div><div class=\"pbar\"><i style=\"width:${QZ.idx/n*100}%\"></i></div>\n <div class=\"card\"><span class=\"qtype ${q.type}\">${esc(typeLabel(q.type))}${isMulti(q)?' — '+T('quiz.multi','coche toutes les bonnes réponses'):''}</span>${q.scen?`<div class=\"scen\">🩺 ${esc(q.scen)}</div>`:''}${img}<div class=\"qq\">${esc(q.q)}</div><div id=\"opts\">${opts}</div><div id=\"fb\"></div>\n <button class=\"btn coral\" id=\"vbtn\" ${q.type==='saisie'?'':'disabled'}>${T('quiz.validate','Valider')}</button>${q.type==='saisie'?`<button class=\"btn ghost\" id=\"idk\">${T('quiz.idk','Je ne sais pas')}</button>`:''}</div>`},{portable:false,after:()=>{const q=curQ();const multi=isMulti(q);QZ.sel=[];QZ.ans=false;\n $$('#opts .opt').forEach(b=>b.onclick=()=>{if(QZ.ans||EDITMODE)return;const i=+b.dataset.i;if(multi){b.classList.toggle('sel');QZ.sel=$$('#opts .opt.sel').map(x=>+x.dataset.i)}else{$$('#opts .opt').forEach(x=>x.classList.remove('sel'));b.classList.add('sel');QZ.sel=[i];if(q.type==='vf'){validate();return}}$('#vbtn').disabled=!QZ.sel.length});\n $('#vbtn').onclick=()=>{if(EDITMODE)return;if(QZ.ans)nextQ();else validate()};\n const t=$('#tin');if(t){t.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();QZ.ans?nextQ():validate()}});const idk=$('#idk');idk.onclick=()=>{if(!QZ.ans&&!EDITMODE){t.value='';validate(true)}}}}});\nfunction normA(s){return nrm(s).replace(/^(le |la |les |l'|un |une |des )/,'').replace(/[^a-z0-9]/g,'')}\nfunction checkSaisie(q,user){const u=normA(user);return u.length>0&&(q.answer||[]).some(a=>{const b=normA(a);return u===b||(u.length>=5&&(b.includes(u)||u.includes(b)))})}\nfunction validate(skip){const q=curQ();let ok=false,user='';\n if(q.type==='saisie'){user=$('#tin').value.trim();ok=!skip&&checkSaisie(q,user);$('#tin').disabled=true}\n else{const want=Array.isArray(q.answer)?q.answer.slice().sort():[q.answer];const got=QZ.sel.slice().sort();ok=want.length===got.length&&want.every((v,i)=>v===got[i]);user=got.map(i=>q.type==='vf'?(i?Tx('quiz.false','Faux'):Tx('quiz.true','Vrai')):q.options[i]).join(' · ');\n  $$('#opts .opt').forEach(b=>{const i=+b.dataset.i,isW=want.includes(i),isS=got.includes(i);b.classList.remove('sel');if(isW&&isS)b.classList.add('ok');else if(isS)b.classList.add('ko');else if(isW)b.classList.add(got.length?'miss':'ok')})}\n QZ.ans=true;if(ok)QZ.score++;\n const st=S.qs[q.id]||{s:0,c:0};st.s++;if(ok)st.c++;st.l=ok?1:0;S.qs[q.id]=st;addXP(ok?10:2);QZ.answers.push({id:q.id,ok,user});\n const ni=nearImg(q);\n $('#fb').innerHTML=`<div class=\"fb ${ok?'good':'bad'}\"><div class=\"h\">${ok?T('quiz.good','✅ Bonne réponse ! +10 XP'):'❌ '+(skip?T('quiz.expected','Réponse attendue'):T('quiz.bad','Pas tout à fait'))}</div>${!ok||q.type==='saisie'?`<div><b>${T('quiz.answer','Réponse :')}</b> ${esc(answerText(q))}</div>`:''}${q.exp?`<div style=\"margin-top:4px\">${esc(q.exp)}</div>`:''}${q.snip&&hasPage(q.src,q.page)?`<div class=\"src\">${T('quiz.snip','📖 Extrait du cours :')} « ${esc(q.snip)} »</div>`:''}${q.page?(hasPage(q.src,q.page)?`<button class=\"linkbtn\" onclick=\"openSource('${jsq(q.src)}',${+q.page})\">${T('ui.srcpage','📖 Page source p.{p}',{p:q.page})}</button>`:`<div class=\"src\">${T('ui.srcref','📖 Source : {s}, page {p}',{s:esc(srcName(q.src)),p:q.page})}</div>`):''}${ni?`<div style=\"margin-top:10px\"><img class=\"qimg\" src=\"${IMG[ni.id]}\" onclick=\"openLB('${jsq(ni.id)}')\"><div class=\"qimgcap\">🖼️ ${esc(ni.cap)} · p.${ni.page}</div></div>`:''}</div>`;\n $('#vbtn').disabled=false;$('#vbtn').innerHTML=QZ.idx+1<QZ.ids.length?T('quiz.next','Question suivante →'):T('quiz.finish','Voir mon résultat 🏁');const idk=$('#idk');if(idk)idk.remove();\n if(QZ.boss==null){S.save={ids:QZ.ids,idx:QZ.idx+1,score:QZ.score,label:QZ.label,subj:QZ.subj,answers:QZ.answers};save()}\n setTimeout(()=>{const f=$('#fb');if(f)f.scrollIntoView({behavior:'smooth',block:'nearest'})},50)}\nfunction nextQ(){QZ.idx++;if(QZ.idx>=QZ.ids.length){finishQuiz();return}render();window.scrollTo(0,0)}\nfunction quitQuiz(){if(QZ.boss==null&&QZ.idx<QZ.ids.length)toast(Tx('toast.saved','Progression sauvegardée : tu pourras reprendre'));VSTACK=[];go('home',{},false)}\nfunction finishQuiz(){const n=QZ.ids.length,sc=QZ.score;S.hist.push({d:today(),n,sc,label:QZ.label});if(S.hist.length>60)S.hist.shift();\n let bossWin=null;if(QZ.boss!=null){const need=Math.ceil(n*0.7);if(sc>=need&&!S.bosses[QZ.boss]){S.bosses[QZ.boss]=1;addXP(100);bossWin=true}else if(sc<need)bossWin=false}\n else S.save=null;if(QZ.subj!=null){S.subj=S.subj||{};const o=S.subj[QZ.subj]||{best:0,n:0,tries:0};o.tries++;o.n=n;o.last=sc;if(sc>o.best)o.best=sc;S.subj[QZ.subj]=o}save();VSTACK=[];go('result',{n,sc,boss:QZ.boss,bossWin,answers:QZ.answers,label:QZ.label},false)}\nB('result.score','Score',()=>{const{n,sc,boss,bossWin}=ctx;const pct=Math.round(sc/n*100);const Bo=boss!=null?DATA.bosses[boss]:null;\n const msg=pct>=80?T('result.m80','Excellent travail ! 🌟'):pct>=60?T('result.m60','Bien joué, continue ! 💪'):pct>=40?T('result.m40','Encore un effort 📚'):T('result.m0','Relis le cours et réessaie 🔁');\n return `<div class=\"card center\"><div style=\"font-size:54px\">${Bo?(bossWin?'🏆':Bo.emo):pct>=80?'🎉':'📊'}</div><div class=\"big\">${sc}/${n}</div><div style=\"font-weight:800;font-size:20px;margin:6px 0\">${pct} % · ${msg}</div>${ctx.label?`<div class=\"small muted\">${esc(ctx.label)}</div>`:''}\n ${Bo?`<div class=\"fb ${bossWin?'good':'bad'}\">${bossWin?`<div class=\"h\">${T('result.bosswin','{name} est vaincu ! +100 XP',{name:esc(Bo.name)})}</div>${T('result.bosswin.sub','Avatar légendaire {emo} débloqué dans ton profil.',{emo:Bo.emo})}`:bossWin===false?`<div class=\"h\">${T('result.bosslose','{name} résiste…',{name:esc(Bo.name)})}</div>${T('result.bosslose.sub','Il faut au moins 70 % ({need}/{n}). Révise : {chs}.',{need:Math.ceil(n*.7),n,chs:Bo.chs.map(c=>esc(chOf(c).short)).join(', ')})}`:T('result.bossagain','Boss déjà vaincu : entraînement terminé.')}</div>`:''}</div>`},{portable:false});\nB('result.review','Correction détaillée',()=>`<div class=\"card\"><h3>${T('result.review','Correction')}</h3>${ctx.answers.map(a=>{const q=QI[a.id];if(!q)return'';return `<div class=\"rv ${a.ok?'okk':''}\"><div><b>${a.ok?'✅':'❌'}</b> ${esc(q.q)}</div>${a.ok?'':`<div class=\"small\"><b>${T('quiz.answer','Réponse :')}</b> ${esc(answerText(q))}${a.user?' · <span class=\"muted\">'+T('result.yours','ta réponse : {u}',{u:esc(a.user)})+'</span>':''}</div>`}${q.page?(hasPage(q.src,q.page)?`<button class=\"linkbtn\" style=\"margin-top:4px\" onclick=\"openSource('${jsq(q.src)}',${+q.page})\">📖 p.${q.page}</button>`:`<div class=\"small muted\">📖 ${esc(srcName(q.src))}, p.${q.page}</div>`):''}</div>`}).join('')}</div>`,{portable:false});\nB('result.actions','Boutons de fin',()=>`${ctx.answers.some(a=>!a.ok)?`<button class=\"btn coral\" onclick=\"startQuiz(shuffle(ctx.answers.filter(a=>!a.ok).map(a=>a.id)),'${jsq(Tx('result.redo.label','Reprise des erreurs'))}')\">${T('result.redo','🔁 Refaire mes erreurs')}</button>`:''}<button class=\"btn\" onclick=\"tab('home')\">${T('result.home','🏠 Accueil')}</button>`,{portable:false});\n\n/* ======================= CONFIGURATION DU QUIZ ======================= */\nlet CFG=null;\nfunction QPARTS(){const L=PARTS.filter(p=>DATA.questions.some(q=>(chOf(q.ch)||{}).part===p.id));return L.length?L:PARTS}\nfunction cfgInit(){if(!CFG)CFG={parts:QPARTS().map(p=>p.id),chs:null,types:TYPES.filter(t=>DATA.questions.some(q=>q.type===t)),n:'20',mode:'all'}}\n/* ---------- sujets type examen : toutes les questions réparties en sujets distincts de 50 ---------- */\nconst SUBJ_N=50;\nfunction subjHash(x){let h=2166136261;x=String(x);for(let i=0;i<x.length;i++){h^=x.charCodeAt(i);h=Math.imul(h,16777619)}return h>>>0}\nfunction subjects(){const by={};DATA.questions.forEach(q=>{(by[q.ch]=by[q.ch]||[]).push(q)});\n const lists=DATA.chapters.map(c=>(by[c.id]||[]).slice().sort((a,b)=>subjHash('s'+a.id)-subjHash('s'+b.id))).filter(l=>l.length);\n Object.keys(by).forEach(k=>{if(!DATA.chapters.some(c=>c.id===k))lists.push(by[k])});\n const tot=lists.reduce((a,l)=>a+l.length,0),order=[];const pos=lists.map(()=>0);\n /* répartition proportionnelle : chaque chapitre est étalé sur tous les sujets */\n const keyed=[];lists.forEach((l,li)=>l.forEach((q,k)=>keyed.push({q,key:(k+0.5)/l.length,li})));\n keyed.sort((a,b)=>a.key-b.key||a.li-b.li);keyed.forEach(x=>order.push(x.q.id));\n const out=[];for(let i=0;i<order.length;i+=SUBJ_N)out.push(order.slice(i,i+SUBJ_N));\n if(out.length>1&&out[out.length-1].length<SUBJ_N/2){const last=out.pop();last.forEach((id,i)=>out[i%out.length].push(id))}\n return out}\nfunction startSubject(k){const sj=subjects()[k];if(!sj)return;startQuiz(shuffle(sj),Tx('config.subj.label','Sujet type examen n°{k}',{k:k+1}),{subj:k})}\nB('config.subjects','Sujets type examen',()=>{const L=subjects();const st=S.subj||{};\n return `<div class=\"card\"><h3>${T('config.subj.title','📝 Sujets type examen')}</h3><div class=\"small muted\" style=\"margin-bottom:12px\">${T('config.subj.sub','Toutes les questions réparties en {k} sujets distincts d’environ {n} questions, sans doublon, chacun couvrant tout le programme.',{k:L.length,n:SUBJ_N})}</div>\n <div style=\"display:grid;grid-template-columns:repeat(var(--cols,2),minmax(0,1fr));gap:10px\">${L.map((ids,k)=>{const o=st[k];const pct=o?Math.round(o.best/o.n*100):null;\n return `<div class=\"tile\" style=\"min-height:96px;padding:14px\" onclick=\"startSubject(${k})\"><div style=\"font-weight:800;font-size:calc(16px*var(--ts,1))\">${T('config.subj.name','Sujet type examen n°{k}',{k:k+1})}</div><div class=\"small muted\">${T('config.subj.n','{n} questions',{n:ids.length})}</div><div class=\"small\" style=\"font-weight:700;color:${pct==null?'var(--grey)':pct>=50?'var(--green)':'var(--red)'}\">${pct==null?T('config.subj.todo','À faire'):T('config.subj.best','Meilleur score : {s}/{n} ({p} %)',{s:o.best,n:o.n,p:pct})}</div></div>`}).join('')}</div></div>`},{portable:false});\nB('config.main','Réglages du quiz',()=>{cfgInit();const chs=CFG.chs||DATA.chapters.filter(c=>CFG.parts.includes(c.part)).map(c=>c.id);\n const avail=pick({chs,types:CFG.types,mode:CFG.mode}).length;const TT=TYPES.filter(t=>DATA.questions.some(q=>q.type===t));\n return `<div class=\"card\"><h3>${T('config.custom','🎛️ Quiz personnalisé')}</h3>${QPARTS().length>1?`<div class=\"lbl2\">${T('config.part','Partie')}</div><div class=\"chips\">${QPARTS().map(p=>`<span class=\"chip ${CFG.parts.includes(p.id)?'on':''}\" onclick=\"togPart('${jsq(p.id)}')\">${esc(p.name)}</span>`).join('')}</div>`:''}\n <div class=\"lbl2\">${T('config.chapters','Chapitres')} <span class=\"small muted\">${T('config.nsel','({n} sélectionnés)',{n:chs.length})}</span></div><div class=\"chips\"><span class=\"chip co ${!CFG.chs?'on':''}\" onclick=\"CFG.chs=null;render()\">${T('ui.alls','Tous')}</span>${DATA.chapters.filter(c=>CFG.parts.includes(c.part)).map(c=>`<span class=\"chip ${CFG.chs&&CFG.chs.includes(c.id)?'on':''}\" onclick=\"togCh('${jsq(c.id)}')\">${c.emo} ${esc(c.short)}</span>`).join('')}</div>\n <div class=\"lbl2\">${T('config.types','Types de questions')}</div><div class=\"chips\">${TT.map(t=>`<span class=\"chip ${CFG.types.includes(t)?'on':''}\" onclick=\"togType('${t}')\">${esc(typeLabel(t))}</span>`).join('')}</div>\n <div class=\"lbl2\">${T('config.sel','Sélection')}</div><div class=\"chips\">${[['all',T('config.m.all','Toutes')],['new',T('config.m.new','Jamais vues')],['weak',T('config.m.weak','Non maîtrisées')],['err',T('config.m.err','Mes erreurs')]].map(m=>`<span class=\"chip ${CFG.mode===m[0]?'on':''}\" onclick=\"CFG.mode='${m[0]}';render()\">${m[1]}</span>`).join('')}</div>\n <div class=\"lbl2\">${T('config.count','Nombre de questions')}</div><div class=\"chips\">${['10','20','40','60','all'].map(x=>`<span class=\"chip ${CFG.n===x?'on':''}\" onclick=\"CFG.n='${x}';render()\">${x==='all'?T('config.m.all','Toutes'):x}</span>`).join('')}</div>\n <div class=\"small muted\" style=\"margin-top:12px\">${T('config.avail','{n} question(s) disponible(s) avec ces filtres.',{n:avail})}</div></div>\n <button class=\"btn coral\" id=\"cfgGo\" ${avail?'':'disabled'} onclick=\"startQuiz(pick({chs:CFG.chs||DATA.chapters.filter(c=>CFG.parts.includes(c.part)).map(c=>c.id),types:CFG.types,mode:CFG.mode,n:CFG.n}),'${jsq(Tx('config.label','Quiz personnalisé'))}')\">${T('config.go','🚀 Lancer ({n} questions)',{n:CFG.n==='all'?avail:Math.min(avail,+CFG.n)})}</button>`},{portable:false});\nfunction togPart(p){const i=CFG.parts.indexOf(p);if(i>=0){if(CFG.parts.length>1)CFG.parts.splice(i,1)}else CFG.parts.push(p);CFG.chs=null;render()}\nfunction togCh(c){if(!CFG.chs)CFG.chs=[];const i=CFG.chs.indexOf(c);i>=0?CFG.chs.splice(i,1):CFG.chs.push(c);if(!CFG.chs.length)CFG.chs=null;render()}\nfunction togType(t){const i=CFG.types.indexOf(t);if(i>=0){if(CFG.types.length>1)CFG.types.splice(i,1)}else CFG.types.push(t);render()}\n\n/* ======================= RÉVISER ======================= */\nB('revise.buttons','Boutons de révision',()=>`<button class=\"btn coral\" onclick=\"go('config')\">${T('revise.custom','🎯 Quiz personnalisé')}</button><button class=\"btn\" onclick=\"startQuiz(pick({mode:'weak',n:20}),'${jsq(Tx('revise.smart.label','Révision intelligente'))}')\">${T('revise.smart','🧠 Révision intelligente (20 non maîtrisées)')}</button><button class=\"btn light\" onclick=\"startQuiz(pick({mode:'new',n:20}),'${jsq(Tx('home.t.new','Jamais vues'))}')\">${T('revise.new','🆕 Questions pas encore traitées ({n})',{n:DATA.questions.filter(q=>!S.qs[q.id]).length})}</button>`);\nB('revise.grid','Grille de révision',()=>{const cnt=t=>DATA.questions.filter(q=>q.type===t).length;return grid('revise.grid',[\n {id:'flash',e:'🃏',l:T('revise.t.flash','Flashcards (Leitner)'),n:T('home.t.flash.n','{n} fiches',{n:CARDS.length}),on:\"go('flashcfg')\",c:'#DFF3F0'},\n {id:'exam',e:'📝',l:T('revise.t.exam','Examen blanc'),n:T('revise.t.exam.n','{n} q · {m} min · correction finale',{n:META.exam.n,m:META.exam.min}),on:'startExam()',c:'#FFE3DC'},\n {id:'cas',e:'🩺',l:T('home.t.cas','Cas cliniques'),n:T('home.t.cas.n','{n} cas',{n:cnt('cas')}),on:\"startQuiz(pick({types:['cas']}),'\"+jsq(Tx('home.t.cas','Cas cliniques'))+\"')\",c:'#E2EEFF',show:cnt('cas')>0},\n {id:'img',e:'🖼️',l:T('revise.t.img','Lecture de schémas'),n:T('revise.t.img.n','{n} questions',{n:cnt('img')}),on:\"startQuiz(pick({types:['img']}),'\"+jsq(Tx('revise.t.img','Lecture de schémas'))+\"')\",c:'#FFE2F1',show:cnt('img')>0},\n {id:'vf',e:'✔️',l:T('revise.t.vf','Vrai / Faux'),n:T('revise.t.vf.n','{n} affirmations',{n:cnt('vf')}),on:\"startQuiz(pick({types:['vf'],n:30}),'\"+jsq(Tx('revise.t.vf','Vrai / Faux'))+\"')\",c:'#FFF1CC',show:cnt('vf')>0},\n {id:'qroc',e:'✍️',l:T('revise.t.qroc','QROC'),n:T('revise.t.qroc.n','{n} réponses courtes',{n:cnt('saisie')}),on:\"startQuiz(pick({types:['saisie'],n:20}),'QROC')\",c:'#EDE4FF',show:cnt('saisie')>0},\n {id:'errors',e:'❌',l:T('home.t.errors','Mes erreurs'),n:T('home.t.errors.n','{n} à revoir',{n:errorIds().length}),on:'startErrors()',c:'#FDECEC'},\n {id:'numbers',e:'🔢',l:T('home.t.numbers','Chiffres clés'),n:T('home.t.numbers.n','{n} données',{n:DATA.numbers.length}),on:\"go('numbers')\",c:'#DFF3F0',show:DATA.numbers.length>0}])},{grid:1});\nB('revise.campaign','Campagne (liste)',()=>DATA.bosses.length?`<div class=\"secT\">${T('revise.campaign','⚔️ Campagne')}</div>${campaignList()}`:'');\nfunction campaignList(){const nb=nextBoss();return DATA.bosses.map((b,i)=>{const done=S.bosses[i],lock=!done&&i>nb&&nb>=0;return `<div class=\"chl\" onclick=\"${lock?\"toast('\"+jsq(Tx('toast.bosslock','Bats d’abord le boss précédent 🔒'))+\"')\":'startBoss('+i+')'}\" style=\"${lock?'opacity:.5':''}\"><div class=\"em\" style=\"background:${done?'#E6F7EE':'#EDE4FF'}\">${lock?'🔒':b.emo}</div><div class=\"tx\"><b>${T('campaign.row','Niveau {n} · {name}',{n:i+1,name:esc(b.name)})}</b><small>${esc(b.lvl||'')} · ${b.chs.map(c=>esc(chOf(c).short)).join(', ')}</small></div><span style=\"font-size:22px\">${done?'🏆':'⚔️'}</span></div>`}).join('')}\nB('campaign.intro','Règles de la campagne',()=>`<div class=\"card small\">${T('campaign.rules','Chaque boss pose <b>12 questions</b> sur ses chapitres. Obtiens au moins <b>70 %</b> pour le vaincre, gagner <b>100 XP</b> et débloquer son <b>avatar légendaire</b>.')}</div>`);\nB('campaign.list','Liste des boss',()=>campaignList());\nfunction startBoss(i){const nb=nextBoss();if(!S.bosses[i]&&nb>=0&&i>nb){toast(Tx('toast.bosslock','Bats d’abord le boss précédent 🔒'));return}const b=DATA.bosses[i];startQuiz(pick({chs:b.chs,n:12}),b.name,{boss:i})}\n\n/* ======================= EXAMEN BLANC ======================= */\nlet EX=null;\nfunction startExam(){const ids=pick({n:META.exam.n});if(!ids.length){toast(Tx('toast.noq','Aucune question pour ces critères'));return}EX={ids,idx:0,ans:{},t0:Date.now(),dur:META.exam.min*60*1000};touchStreak();go('exam')}\nB('exam.main','Question d’examen',()=>{const q=QI[EX.ids[EX.idx]];const L='ABCDEFGH';const a=EX.ans[q.id];let opts='';const multi=Array.isArray(q.answer)&&q.type!=='saisie';\n if(q.type==='saisie')opts=`<input class=\"tin\" id=\"etin\" value=\"${esc(a||'')}\" placeholder=\"${esc(Tx('quiz.input','Ta réponse…'))}\" autocomplete=\"off\">`;\n else if(q.type==='vf')opts=`<div class=\"vfrow\">${[0,1].map(i=>`<button class=\"opt ${a&&a.includes(i)?'sel':''}\" data-i=\"${i}\">${i?T('quiz.vfalse','✖️ Faux'):T('quiz.vtrue','✔️ Vrai')}</button>`).join('')}</div>`;\n else opts=q.options.map((o,i)=>`<button class=\"opt ${a&&a.includes(i)?'sel':''}\" data-i=\"${i}\"><span class=\"k\">${L[i]}</span><span>${esc(o)}</span></button>`).join('');\n return `<div class=\"pbar\"><i style=\"width:${Object.keys(EX.ans).length/EX.ids.length*100}%\"></i></div><div class=\"card\"><span class=\"qtype ${q.type}\">${esc(typeLabel(q.type))}${multi?' — '+T('exam.multi','plusieurs réponses'):''}</span>${q.scen?`<div class=\"scen\">🩺 ${esc(q.scen)}</div>`:''}${q.type==='img'&&IMG[q.img]?`<img class=\"qimg\" src=\"${IMG[q.img]}\">`:''}<div class=\"qq\">${esc(q.q)}</div><div id=\"opts\">${opts}</div></div>\n <div style=\"display:flex;gap:10px\">${EX.idx>0?`<button class=\"btn light\" onclick=\"exNav(-1)\">${T('exam.prev','‹ Préc.')}</button>`:''}${EX.idx<EX.ids.length-1?`<button class=\"btn\" onclick=\"exNav(1)\">${T('exam.next','Suiv. ›')}</button>`:''}</div>\n <button class=\"btn coral\" onclick=\"if(confirm('${jsq(Tx('exam.confirm','Terminer et corriger ?'))}'))finishExam()\">${T('exam.finish','🏁 Terminer l’examen ({a}/{n} répondues)',{a:Object.keys(EX.ans).length,n:EX.ids.length})}</button>`},{portable:false,after:()=>{const q=QI[EX.ids[EX.idx]];const multi=Array.isArray(q.answer)&&q.type!=='saisie';\n $$('#opts .opt').forEach(b=>b.onclick=()=>{if(EDITMODE)return;const i=+b.dataset.i;let a=EX.ans[q.id]||[];if(multi){a=a.includes(i)?a.filter(x=>x!==i):a.concat(i)}else a=[i];if(a.length)EX.ans[q.id]=a;else delete EX.ans[q.id];$$('#opts .opt').forEach(x=>x.classList.toggle('sel',a.includes(+x.dataset.i)))});\n const t=$('#etin');if(t)t.oninput=()=>{if(t.value.trim())EX.ans[q.id]=t.value;else delete EX.ans[q.id]};\n clearInterval(EX.ti);const tick=()=>{const r=EX.dur-(Date.now()-EX.t0);const e=$('#tmr');if(r<=0){clearInterval(EX.ti);toast(Tx('exam.timeout','⏰ Temps écoulé !'));finishExam();return}if(e)e.textContent='⏱ '+Math.floor(r/60000)+':'+String(Math.floor(r%60000/1000)).padStart(2,'0')};tick();EX.ti=setInterval(tick,1000)}});\nfunction exNav(d){EX.idx+=d;render();window.scrollTo(0,0)}\nfunction finishExam(){clearInterval(EX.ti);let sc=0;const answers=EX.ids.map(id=>{const q=QI[id];const a=EX.ans[id];let ok=false,user='';\n  if(q.type==='saisie'){user=a||'';ok=checkSaisie(q,user)}\n  else if(a){const want=Array.isArray(q.answer)?q.answer.slice().sort():[q.answer];const got=a.slice().sort();ok=want.length===got.length&&want.every((v,i)=>v===got[i]);user=got.map(i=>q.type==='vf'?(i?Tx('quiz.false','Faux'):Tx('quiz.true','Vrai')):q.options[i]).join(' · ')}\n  if(ok)sc++;const st=S.qs[id]||{s:0,c:0};st.s++;if(ok)st.c++;st.l=ok?1:0;S.qs[id]=st;return{id,ok,user}});\n addXP(sc*10);S.exams.push({d:today(),sc,n:EX.ids.length});const note=Math.round(sc/EX.ids.length*200)/10;const label=Tx('exam.label','Examen blanc · note {note}/20',{note});S.hist.push({d:today(),n:EX.ids.length,sc,label});save();\n VSTACK=[];go('result',{n:EX.ids.length,sc,boss:null,answers,label},false);toast(Tx('exam.note','Note : {note} / 20',{note}),3500)}\n\n/* ======================= FLASHCARDS ======================= */\nlet FL=null;\nB('flashcfg.leitner','Boîtes de Leitner',()=>{const box=[0,0,0,0,0];CARDS.forEach(c=>{box[(S.lt[c.id]||{b:0}).b]++});return `<div class=\"card\"><b>${T('flashcfg.leitner','Système de Leitner')}</b><div class=\"small muted\">${T('flashcfg.help','Chaque fiche sue monte d’une boîte ; une fiche ratée revient en boîte 1. Les boîtes basses reviennent plus souvent.')}</div><div class=\"boxes\">${box.map((n,i)=>`<div><b>${n}</b>${T('flashcfg.box','Boîte {i}',{i:i+1})}</div>`).join('')}</div></div>`},{portable:false});\nB('flashcfg.main','Choix des fiches',()=>{const sel=ctx.sel||[];const all=!!ctx.all;const nSel=CARDS.filter(c=>!sel.length||sel.includes(c.ch)).length;\n return `<div class=\"card\"><div class=\"lbl2\" style=\"margin-top:0\">${T('config.chapters','Chapitres')}</div><div class=\"chips\"><span class=\"chip co ${!sel.length?'on':''}\" onclick=\"go('flashcfg',{sel:[],all:${all}},false)\">${T('ui.alls','Tous')}</span>${DATA.chapters.map(c=>`<span class=\"chip ${sel.includes(c.id)?'on':''}\" onclick=\"togFl('${jsq(c.id)}')\">${c.emo} ${esc(c.short)}</span>`).join('')}</div>\n <div class=\"lbl2\">${T('flashcfg.size','Taille de la session')}</div><div class=\"chips\"><span class=\"chip ${!all?'on':''}\" onclick=\"go('flashcfg',{sel:${esc(JSON.stringify(sel))},all:false},false)\">${T('flashcfg.30','30 fiches (priorité aux boîtes basses)')}</span><span class=\"chip ${all?'on':''}\" onclick=\"go('flashcfg',{sel:${esc(JSON.stringify(sel))},all:true},false)\">${T('flashcfg.all','Toutes les fiches ({n})',{n:nSel})}</span></div></div>\n <button class=\"btn coral\" onclick=\"startFlash(ctx.sel,ctx.all)\">${T('flashcfg.go','▶ Commencer ({n} fiches)',{n:all?nSel:Math.min(30,nSel)})}</button>`},{portable:false});\nfunction togFl(c){const s=(ctx.sel||[]).slice();const i=s.indexOf(c);i>=0?s.splice(i,1):s.push(c);go('flashcfg',{sel:s,all:ctx.all},false)}\nfunction startFlash(chs,all){let deck=CARDS.filter(c=>!chs||!chs.length||chs.includes(c.ch));\n deck=shuffle(deck).sort((a,b)=>((S.lt[a.id]||{b:0}).b)-((S.lt[b.id]||{b:0}).b));if(!all)deck=deck.slice(0,30);if(!deck.length){toast(Tx('toast.nocard','Aucune fiche'));return}FL={deck,i:0,k:0,chs,all};touchStreak();go('flash')}\nB('flash.main','Fiche en cours',()=>{if(FL.i>=FL.deck.length)return `<div class=\"card center\"><div style=\"font-size:54px\">🎉</div><div class=\"big\">${FL.k}/${FL.deck.length}</div><div>${T('flash.known','fiches sues')}</div></div><button class=\"btn coral\" onclick=\"startFlash(FL.chs,FL.all)\">${T('flash.again','🔁 Nouvelle session')}</button><button class=\"btn light\" onclick=\"back()\">${Tx('ui.back','← Retour')}</button>`;\n const c=FL.deck[FL.i];\n return `<div class=\"fc\"><div class=\"fci\" id=\"fci\"><div class=\"fcf\"><div class=\"small muted\" style=\"margin-bottom:10px\">${chOf(c.ch).emo} ${esc(chOf(c.ch).title)}</div>${c.img&&IMG[c.img]?`<img src=\"${IMG[c.img]}\" style=\"width:100%;border-radius:12px;margin-bottom:10px\">`:''}<div class=\"q\">${c.front}</div><div class=\"small muted\" style=\"margin-top:14px\">${T('flash.tap','👆 Touche pour retourner')}</div></div><div class=\"fcb\"><div class=\"a\">${esc(c.back)}</div>${c.exp?`<div style=\"margin-top:10px;font-size:15px;opacity:.95\">${esc(c.exp)}</div>`:''}${c.page?`<div style=\"margin-top:12px;font-size:13px;opacity:.8\">📖 ${esc(srcName(c.src))} p.${c.page}</div>`:''}</div></div></div>\n <div style=\"display:flex;gap:10px\"><button class=\"btn\" style=\"background:var(--red)\" onclick=\"flAns(0)\">${T('flash.again1','🔁 À revoir')}</button><button class=\"btn\" style=\"background:var(--green)\" onclick=\"flAns(1)\">${T('flash.knew','✅ Je savais')}</button></div>${c.page?`<button class=\"btn light\" onclick=\"openSource('${jsq(c.src)}',${+c.page})\">${T('ui.srcpage','📖 Page source p.{p}',{p:c.page})}</button>`:''}`},{portable:false,after:()=>{const f=$('#fci');if(f){f.onclick=()=>{if(!EDITMODE)f.classList.toggle('flip')};const h=Math.max(...$$('.fcf,.fcb',f).map(x=>x.scrollHeight));f.style.minHeight=Math.max(300,h)+'px'}}});\nfunction flAns(k){const c=FL.deck[FL.i];const s=S.lt[c.id]||{b:0};s.b=k?Math.min(4,s.b+1):0;S.lt[c.id]=s;if(k){FL.k++;S.flashKnown++;addXP(3)}save();FL.i++;render();window.scrollTo(0,0)}\n\n/* ======================= CHIFFRES, GLOSSAIRE, IMAGES ======================= */\nB('numbers.list','Chiffres clés',()=>{const h=!!ctx.hide;return `<button class=\"btn ${h?'':'coral'}\" onclick=\"go('numbers',{hide:${!h}},false)\">${h?T('numbers.show','👁️ Tout afficher'):T('numbers.hide','🙈 Mode quiz : cacher les chiffres')}</button>`+DATA.chapters.map(c=>{const ns=DATA.numbers.filter(n=>n.ch===c.id);if(!ns.length)return'';return `<div class=\"secT\" style=\"font-size:18px\">${c.emo} ${esc(c.title)}</div>`+ns.map(n=>`<div class=\"num ${h?'hide':''}\" onclick=\"this.classList.remove('hide')\"><div class=\"v\">${esc(n.v)}</div><div>${esc(n.l)}</div></div>`).join('')}).join('')});\nB('glossary.list','Glossaire',()=>`<div class=\"search\" style=\"margin-bottom:12px\">🔍<input class=\"gq\" placeholder=\"${esc(Tx('glossary.ph','Chercher un terme…'))}\"></div><div class=\"glist\"></div>`,{after:()=>$$('.gq').forEach(inp=>{const out=inp.closest('.blk').querySelector('.glist');const r=()=>{const v=nrm(inp.value);out.innerHTML=DATA.glossary.slice().sort((a,b)=>a.t.localeCompare(b.t,'fr')).filter(g=>!v||nrm(g.t+' '+g.d).includes(v)).map(g=>`<div class=\"gl\"><b>${esc(g.t)}</b> ${pill(g.ch)}<div>${esc(g.d)}</div></div>`).join('')};inp.oninput=r;r()})});\nlet LBL=[],LBI=0;\nB('images.gallery','Galerie d’images',()=>{const f=ctx.f||'all';const list=DATA.images.filter(i=>IMG[i.id]&&(f==='all'||i.src===f||i.ch===f||chOf(i.ch).part===f));LBL=list;const st=VIEW==='images'?'false':'true';\n return `${PARTS.length>1?`<div class=\"chips\" style=\"margin-bottom:10px\">${[['all',Tx('ui.all','Tout')]].concat(PARTS.map(p=>[p.id,p.name])).map(x=>`<span class=\"chip ${f===x[0]?'on':''}\" onclick=\"go('images',{f:'${jsq(x[0])}'},${st})\">${esc(x[1])}</span>`).join('')}</div>`:''}\n <select class=\"tin\" style=\"margin-bottom:12px\" onchange=\"go('images',{f:this.value||'all'},${st})\"><option value=\"\">${esc(Tx('images.filter','— Par chapitre —'))}</option>${DATA.chapters.map(c=>`<option value=\"${esc(c.id)}\" ${f===c.id?'selected':''}>${esc(c.title)}</option>`).join('')}</select>\n <div class=\"small muted\" style=\"margin-bottom:8px\">${T('images.count','{n} planche(s)',{n:list.length})}</div><div class=\"gal\">${list.map(i=>`<div class=\"gi\" onclick=\"openLB('${jsq(i.id)}',LBL)\"><div class=\"th\" style=\"background-image:url(${IMG[i.id]})\"></div><div class=\"c\">${esc(i.cap)}<br><span class=\"muted\">${esc(srcName(i.src))} · p.${i.page}</span></div></div>`).join('')}</div>`});\nfunction openLB(id,list){LBL=list&&list.length?list:DATA.images.filter(i=>IMG[i.id]);LBI=Math.max(0,LBL.findIndex(i=>i.id===id));showLB();$('#lb').classList.add('on')}\nfunction showLB(){const i=LBL[LBI];if(!i)return;$('#lbimg').src=IMG[i.id];$('#lbcap').textContent=i.cap+' — '+srcName(i.src)+' p.'+i.page}\n\n/* ======================= STATISTIQUES ======================= */\nB('stats.kpis','Indicateurs',()=>{let seen=0,att=0,cor=0;Object.keys(S.qs).forEach(k=>{if(!QI[k])return;const s=S.qs[k];seen++;att+=s.s;cor+=s.c});const acc=att?Math.round(cor/att*100):0;\n return `<div class=\"kpis\"><div class=\"kpi\"><b>${S.xp}</b><span>${T('stats.k.xp','XP total · niv. {n}',{n:level().n})}</span></div><div class=\"kpi\"><b>${acc} %</b><span>${T('stats.k.acc','taux de réussite')}</span></div><div class=\"kpi\"><b>${seen}/${DATA.questions.length}</b><span>${T('stats.k.seen','questions vues')}</span></div><div class=\"kpi\"><b>🔥 ${S.streak.count}</b><span>${T('stats.k.streak','jours de série')}</span></div><div class=\"kpi\"><b>${mastered()}/${DATA.chapters.length}</b><span>${T('stats.k.mastered','chapitres maîtrisés')}</span></div><div class=\"kpi\"><b>${Object.keys(S.read).length}/${DATA.course.length}</b><span>${T('stats.k.read','pages lues')}</span></div></div><div style=\"height:14px\"></div>`});\nB('stats.mastery','Maîtrise par chapitre',()=>`<div class=\"card\"><h3>${T('stats.mastery','Maîtrise par chapitre')}</h3>${PARTS.map(p=>`<div class=\"lbl2\">${esc(p.name)}</div>`+DATA.chapters.filter(c=>c.part===p.id).map(c=>{const m=chMastery(c.id);return `<div class=\"sbar\" onclick=\"go('chapter',{id:'${jsq(c.id)}'})\"><span class=\"nmx\">${c.emo} ${esc(c.short)}</span><span class=\"tr\"><i style=\"width:${m.pct}%;background:${mColor(c.id)}\"></i></span><span class=\"pc\">${m.pct}%</span></div>`}).join('')).join('')}</div>`);\nB('stats.types','Réussite par type',()=>{const byType={};DATA.questions.forEach(q=>{const s=S.qs[q.id];if(!s)return;const t=byType[q.type]=byType[q.type]||[0,0];t[0]+=s.c;t[1]+=s.s});\n return `<div class=\"card\"><h3>${T('stats.types','Réussite par type')}</h3>${TYPES.filter(t=>DATA.questions.some(q=>q.type===t)).map(t=>{const v=byType[t];const p=v&&v[1]?Math.round(v[0]/v[1]*100):0;return `<div class=\"sbar\"><span class=\"nmx\">${esc(typeLabel(t))}</span><span class=\"tr\"><i style=\"width:${p}%;background:var(--turq)\"></i></span><span class=\"pc\">${v?p+'%':'–'}</span></div>`}).join('')}</div>`});\nB('stats.weak','Points faibles',()=>{const weak=DATA.chapters.map(c=>({c,m:chMastery(c.id)})).filter(x=>x.m.seen).sort((a,b)=>a.m.pct-b.m.pct).slice(0,5);\n return weak.length?`<div class=\"card\"><h3>${T('stats.weak','🎯 Points faibles')}</h3>${weak.map(x=>`<div class=\"chl\" onclick=\"startQuiz(pick({chs:['${jsq(x.c.id)}'],mode:'weak',n:15}),'${jsq(Tx('stats.weak.label','Points faibles'))}')\"><div class=\"em\">${x.c.emo}</div><div class=\"tx\"><b>${esc(x.c.title)}</b><small>${T('stats.weak.row','{p} % · entraîne-toi',{p:x.m.pct})}</small></div>⚡</div>`).join('')}</div>`:''});\nB('stats.hist','Historique',()=>`<div class=\"card\"><h3>${T('stats.hist','Historique')}</h3>${S.hist.length?S.hist.slice(-12).reverse().map(h=>`<div class=\"sbar\"><span class=\"nmx\">${h.d}<br><small class=\"muted\">${esc(h.label||'')}</small></span><span class=\"tr\"><i style=\"width:${Math.round(h.sc/h.n*100)}%;background:var(--coral)\"></i></span><span class=\"pc\">${h.sc}/${h.n}</span></div>`).join(''):`<div class=\"muted\">${T('stats.nohist','Aucun quiz terminé pour le moment.')}</div>`}</div>`);\n\n/* ======================= PROFIL ======================= */\nfunction badges(){const b=DATA.bosses.map((x,i)=>[x.emo+' '+Tx('badge.boss','Boss {n}',{n:i+1}),!!S.bosses[i]]);const answered=Object.keys(S.qs).length;\n return b.concat([[Tx('badge.xp100','🥉 100 XP'),S.xp>=100],[Tx('badge.xp1000','🥈 1000 XP'),S.xp>=1000],[Tx('badge.xp5000','🥇 5000 XP'),S.xp>=5000],[Tx('badge.streak7','🔥 7 jours'),S.streak.count>=7],[Tx('badge.read','📚 Tout lu'),DATA.course.length>0&&Object.keys(S.read).length>=DATA.course.length],[Tx('badge.q100','🎯 100 questions'),answered>=100],[Tx('badge.qall','💯 Toutes les questions vues'),answered>=DATA.questions.length],[Tx('badge.fl100','🃏 100 fiches sues'),S.flashKnown>=100],[Tx('badge.exam14','📝 Examen ≥ 14/20'),S.exams.some(e=>e.sc/e.n>=.7)],[Tx('badge.ch10','🏆 10 chapitres maîtrisés'),mastered()>=10]])}\nB('profile.identity','Identité & avatar',()=>{const L=level();const leg=DATA.bosses.map((b,i)=>({e:b.emo,ok:!!S.bosses[i]}));\n return `<div class=\"card\"><div style=\"display:flex;gap:14px;align-items:center;margin-bottom:12px\"><div class=\"ava\" style=\"background:var(--tint)\">${S.avatar}</div><div><div style=\"font-weight:800;font-size:21px\">${esc(S.name)||T('profile.me','Mon profil')}</div><div class=\"muted\">${T('profile.line','Niveau {n} · {name} · {xp} XP · série {s} j',{n:L.n,name:esc(L.name),xp:S.xp,s:S.streak.count})}</div></div></div>\n <input class=\"tin pname\" value=\"${esc(S.name)}\" placeholder=\"${esc(Tx('profile.name.ph','Ton prénom et nom'))}\">\n <div class=\"lbl2\">${T('profile.avatar','Choisis ton personnage')}</div>\n ${Object.entries(AVATARS).map(([k,l],i)=>`<details class=\"cat\" ${i===0?'open':''}><summary>${l[0]} ${esc(k)} · ${l.length}</summary><div class=\"avgrid\">${l.map(a=>`<button class=\"${S.avatar===a?'on':''}\" data-a=\"${a}\">${a}</button>`).join('')}</div></details>`).join('')}\n ${leg.length?`<details class=\"cat\" open><summary>${T('profile.legend','🏆 Légendaires · à débloquer ({ok}/{n})',{ok:leg.filter(x=>x.ok).length,n:leg.length})}</summary><div class=\"avgrid\">${leg.map((x,i)=>`<button class=\"${x.ok?'':'lock'} ${S.avatar===x.e?'on':''}\" data-a=\"${x.e}\" data-lock=\"${x.ok?'':i}\">${x.e}</button>`).join('')}</div><div class=\"small muted\">${T('profile.legend.help','Touche un avatar grisé pour savoir comment le débloquer.')}</div></details>`:''}\n <button class=\"btn coral psave\" style=\"margin-top:12px\">${T('profile.save','Enregistrer')}</button></div>`},{after:()=>{\n $$('.avgrid button').forEach(b=>b.onclick=()=>{if(EDITMODE)return;if(b.dataset.lock){const Bo=DATA.bosses[+b.dataset.lock];toast(Tx('toast.unlock','🔒 Bats « {name} » (niveau {n}) pour débloquer {emo}',{name:Bo.name,n:+b.dataset.lock+1,emo:Bo.emo}),3000);return}S.avatar=b.dataset.a;$$('.avgrid button').forEach(x=>x.classList.toggle('on',x.dataset.a===b.dataset.a))});\n $$('.psave').forEach(b=>b.onclick=()=>{if(EDITMODE)return;S.name=b.closest('.card').querySelector('.pname').value.trim();save();toast(Tx('toast.profile','Profil enregistré ✅'));render()})}});\nB('profile.badges','Badges',()=>`<div class=\"card\"><h3>${T('profile.badges','Badges')}</h3><div class=\"badges\">${badges().map(b=>`<span class=\"badge ${b[1]?'on':''}\">${esc(b[0])}</span>`).join('')}</div></div>`);\nB('profile.colors','Couleurs (étudiant)',()=>{const P=PALETTES(),cur=palette();\n return `<div class=\"card\"><h3>${T('profile.colors','🎨 Couleurs de l’application')}</h3><div class=\"small muted\">${T('profile.colors.help','Choisis une palette ou crée la tienne')}</div>\n <div class=\"thg\">${P.map((c,i)=>`<button class=\"thb ${S.theme&&S.theme.pal===i?'on':''}\" data-t=\"${i}\"><span class=\"sw\" style=\"background:linear-gradient(135deg,${c.w?'#ffffff':c.h1} 0 50%,${c.acc} 50% 75%,${c.acc2} 75%);border:1px solid #ddd\"></span>${esc(c.n)}</button>`).join('')}</div>\n <div class=\"lbl2\">${T('profile.custom','Personnaliser')}</div>${[['h1',T('profile.c.h1','Couleur principale (en-tête, menu)')],['h2',T('profile.c.h2','Couleur secondaire (dégradés)')],['acc',T('profile.c.acc','Couleur des boutons')],['acc2',T('profile.c.acc2','Couleur d’accent')],['bg',T('profile.c.bg','Fond de l’écran')]].map(k=>`<div class=\"hlrow\"><input type=\"color\" data-tk=\"${k[0]}\" value=\"${cur[k[0]]}\"><span>${k[1]}</span></div>`).join('')}\n <button class=\"btn light pdef\">${T('profile.c.default','Palette par défaut de l’appli')}</button></div>`},{after:()=>{\n $$('input[type=color][data-tk]').forEach(i=>i.oninput=()=>{S.theme={custom:Object.assign({},palette(),{[i.dataset.tk]:i.value})};applyLook();save();$$('.thb').forEach(b=>b.classList.remove('on'))});\n $$('.thb').forEach(b=>b.onclick=()=>{if(EDITMODE)return;S.theme={pal:+b.dataset.t};save();applyLook();render();toast(Tx('toast.theme','Palette « {n} » appliquée 🎨',{n:PALETTES()[+b.dataset.t].n}))});\n $$('.pdef').forEach(b=>b.onclick=()=>{if(EDITMODE)return;S.theme=null;save();applyLook();render()})}});\nB('profile.hl','Surligneur (couleurs)',()=>`<div class=\"card\"><h3>${T('profile.hl','🖍️ Surligneur')}</h3><div class=\"small muted\">${T('profile.hl.help','Une couleur par niveau d’importance (modifiable)')}</div>${[T('profile.hl.0','Essentiel'),T('profile.hl.1','À retenir'),T('profile.hl.2','Piège / à revoir')].map((n,i)=>`<div class=\"hlrow\"><input type=\"color\" value=\"${S.hl[i]}\" data-h=\"${i}\"><mark class=\"hl h${i}\" style=\"padding:4px 10px\">${n}</mark></div>`).join('')}<button class=\"btn light hldef\">${T('profile.hl.default','Couleurs par défaut')}</button><div class=\"small muted\">${T('profile.hl.count','{n} page(s) annotée(s)',{n:Object.keys(S.ann).length})}</div></div>`,{after:()=>{\n $$('input[type=color][data-h]').forEach(i=>i.oninput=()=>{S.hl[+i.dataset.h]=i.value;applyLook();save()});\n $$('.hldef').forEach(b=>b.onclick=()=>{if(EDITMODE)return;S.hl=['#FFE08A','#A8E6CF','#FFB3BA'];save();applyLook();render()})}});\nB('profile.data','Mes données',()=>`<div class=\"card\"><h3>${T('profile.data','💾 Mes données')}</h3><div class=\"small muted\" style=\"margin-bottom:10px\">${T('profile.data.help','Ta progression est enregistrée sur cet appareil. Exporte-la pour la transférer sur un autre téléphone.')}</div>\n <button class=\"btn\" onclick=\"exportData()\">${T('profile.export','⬇️ Exporter ma progression')}</button><button class=\"btn light\" onclick=\"$('#imp').click()\">${T('profile.import','⬆️ Importer une progression')}</button>\n <button class=\"btn ghost\" onclick=\"if(confirm('${jsq(Tx('profile.reset.confirm','Effacer toute ta progression ?'))}')){localStorage.removeItem(SKEY);S=load();applyLook();render()}\">${T('profile.reset','🗑️ Réinitialiser')}</button></div>`);\nfunction download(name,text,type){const b=new Blob([text],{type:type||'application/octet-stream'});const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},1500)}\nfunction exportData(){download(APPID+'-progression-'+today()+'.json',JSON.stringify(S),'application/json')}\n\n/* ======================= DÉMARRAGE ======================= */\nconst SHELL=()=>`<div class=\"app\" id=\"app\"></div><nav class=\"nav\" id=\"nav\"></nav>\n<div class=\"palette\" id=\"palette\"><button data-c=\"0\" style=\"background:var(--hl0)\"></button><button data-c=\"1\" style=\"background:var(--hl1)\"></button><button data-c=\"2\" style=\"background:var(--hl2)\"></button><button class=\"er\" data-c=\"x\">⌫</button></div>\n<div class=\"lb\" id=\"lb\"><img id=\"lbimg\" alt=\"\"><div class=\"cap\" id=\"lbcap\"></div><div class=\"ctr\"><button id=\"lbprev\">${esc(Tx('lb.prev','‹ Préc.'))}</button><button id=\"lbsrc\">${esc(Tx('lb.src','📖 Page source'))}</button><button id=\"lbnext\">${esc(Tx('lb.next','Suiv. ›'))}</button><button id=\"lbclose\">${esc(Tx('lb.close','✕ Fermer'))}</button></div></div>\n<div class=\"toast\" id=\"toast\"></div><input type=\"file\" id=\"imp\" accept=\".json,application/json\" class=\"hide\">`;\nfunction bindStatic(){\n document.addEventListener('selectionchange',()=>{clearTimeout(bindStatic._t);bindStatic._t=setTimeout(checkSel,250)});\n $$('#palette button').forEach(b=>{const h=e=>{e.preventDefault();if(!selRange||!selBox)return;const c=b.dataset.c;if(c==='x')eraseRange(selRange,selBox);else wrapRange(selRange,c);persist(selBox);window.getSelection().removeAllRanges();$('#palette').style.display='none';selRange=null};b.addEventListener('mousedown',h);b.addEventListener('touchstart',h,{passive:false})});\n $('#lbprev').onclick=()=>{LBI=(LBI-1+LBL.length)%LBL.length;showLB()};$('#lbnext').onclick=()=>{LBI=(LBI+1)%LBL.length;showLB()};\n $('#lbclose').onclick=()=>$('#lb').classList.remove('on');$('#lbsrc').onclick=()=>{const i=LBL[LBI];$('#lb').classList.remove('on');openSource(i.src,i.page)};\n $('#imp').onchange=e=>{const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{const d=JSON.parse(r.result);if(!d||typeof d!=='object')throw 0;S=Object.assign(load(),d);save();applyLook();toast(Tx('toast.imported','Progression importée ✅'));render()}catch(x){toast(Tx('toast.badfile','Fichier invalide'))}};r.readAsText(f);e.target.value=''}}\nfunction boot(){RO=!window.PORTAIL_EDITOR;S=load();E=normE(EMB);\n if(!RO){let loc=null;try{loc=JSON.parse(localStorage.getItem(EKEY)||'null')}catch(e){}if(loc&&(loc.base||0)>=(EMB.rev||0))E=normE(loc);E.base=EMB.rev||0}\n applyContent();document.body.insertAdjacentHTML('afterbegin',SHELL());buildNav();bindStatic();applyLook();touchStreak();render();\n if(!RO)window.PORTAIL_EDITOR.init();window.PORTAIL_READY=true}\nif(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();\n<%/script>\n</body>\n</html>\n";
